        '《尼布楚条约》：17世纪中期，沙俄入侵占我国黑龙江流域，清政府于1685年和1686年进行反击，取得了雅克萨之战的胜利，1689年中俄经过平等协商签订了第一个边界条约《尼布楚条约》，这个条约从法律上肯定了黑龙江和乌苏里江流域包括库页岛在内的广大地区，都是中国的领土。',
