    indexText: '先秦诗歌小节包括《诗经》的别称、305篇、现实主义源头和风雅颂赋比兴六义，《楚辞》的屈原创体与刘向辑录，以及《离骚》的长篇政治抒情诗地位和“风骚”并称。',
    sourceSections: [9], sourceUnitIds: [PRE_QIN_POETRY_SOURCE_UNITS.heading], sourceAuditStatus: 'ready-for-user-acceptance',
