  if(marketFailureMeaningPoint) Object.assign(marketFailureMeaningPoint,{categoryId:'market-failure',title:'市场失灵的含义',summary:'完整保留市场失灵的定义。',preview:'市场机制不能实现资源有效配置',keywords:['市场失灵','市场机制','资源有效配置'],aliases:['市场机制失灵'],tags:['常识判断','经济常识','微观经济学'],indexText:'市场失灵是市场机制不能实现资源有效配置。',sourceSections:[12],sourceUnitIds:[MARKET_FAILURE_MEANING_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'判断市场失灵只看结果：市场机制运行后，资源仍不能实现有效配置。',focus:[{label:'市场失灵的含义',note:'通过市场机制，资源仍不能实现有效配置，这种情况就是市场失灵。',sourceUnitIds:[MARKET_FAILURE_MEANING_SOURCE_UNITS.meaning]}],route:['含义'],review:['市场失灵的判断主体是市场机制。','核心结果：资源不能实现有效配置。','“市场存在波动”不等同于市场失灵，关键仍是资源配置是否有效。']},tabs:[{id:'market-failure-meaning',title:'含义',blocks:[{type:'list',label:'市场失灵的含义',items:['通过市场机制资源不能实现资源的有效配置，这种情况即为市场失灵。'],highlights:['市场机制','不能实现','资源的有效配置'],sourceUnitIds:[MARKET_FAILURE_MEANING_SOURCE_UNITS.meaning]}]}]});

  const marketFailureFactorsPoint=(points||[]).find((item)=>item.id==='market-failure-factors');
  if(marketFailureFactorsPoint) Object.assign(marketFailureFactorsPoint,{categoryId:'market-failure',title:'导致市场失灵的因素',summary:'按因素总览、垄断、外部性、公共物品、信息不对称5个知识点完整重建。',preview:'垄断；外部性；公共物品；信息不对称；税收补贴与政府供给',keywords:['垄断','外部性','正外部性','负外部性','公共物品','搭便车','信息不对称','逆向选择','道德风险'],aliases:['市场失灵原因'],tags:['常识判断','经济常识','微观经济学'],indexText:'市场失灵因素小节含总览及四类原因与解决方案。',sourceSections:[13,14],sourceUnitIds:[MARKET_FAILURE_FACTORS_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'按“问题—失灵机制—政府处理”学习四类因素：垄断限制供给，外部性让私人与社会成本收益错位，公共物品诱发搭便车，信息不对称产生逆向选择和道德风险。',focus:[
    {label:'导致市场失灵的因素总览',note:'主要原因有垄断、外部性、公共物品和信息不对称。',sourceUnitIds:[MARKET_FAILURE_FACTORS_SOURCE_UNITS.overview]},
    {label:'垄断与市场失灵',note:'垄断者通过控制供给和调节产量影响价格，使市场机制不能正常作用；政府可限制垄断价格并制定反垄断法。',sourceUnitIds:[MARKET_FAILURE_FACTORS_SOURCE_UNITS.monopoly]},
    {label:'外部性与市场失灵',note:'外部性是经济活动给无关第三方的影响；负外部性使社会成本过高，可征税内化成本，正外部性使私人收益不足，可补贴转回外部收益。',sourceUnitIds:[MARKET_FAILURE_FACTORS_SOURCE_UNITS.externality]},
    {label:'公共物品与市场失灵',note:'公共物品具有非竞争性和非排他性，搭便车使其缺少价格和私人供给，市场配置不足，主要由政府提供。',sourceUnitIds:[MARKET_FAILURE_FACTORS_SOURCE_UNITS.publicGoods]},
    {label:'信息不对称与市场失灵',note:'交易双方信息不同会产生事前的逆向选择和事后的道德风险；政府通过信息调控保障充分、正确信息。',sourceUnitIds:[MARKET_FAILURE_FACTORS_SOURCE_UNITS.asymmetry]},
  ],route:['因素总览','垄断','外部性','公共物品','信息不对称'],review:['四类原因：垄断、外部性、公共物品、信息不对称。','垄断控制供给并影响价格；政府可限价并制定反垄断法。','负外部性：社会成本过高，通常征税；正外部性：私人收益不足，通常补贴。','公共物品具有非竞争性、非排他性，搭便车导致私人供给不足，主要由政府提供。','信息不对称：逆向选择多在事前，道德风险多在事后；政府以信息调控应对。']},tabs:[
    {id:'market-failure-overview',title:'因素总览',blocks:[{type:'list',label:'导致市场失灵的因素总览',items:['一般认为，导致市场失灵的原因主要包括垄断、外部性、公共物品和信息不对称。'],highlights:['垄断','外部性','公共物品','信息不对称'],sourceUnitIds:[MARKET_FAILURE_FACTORS_SOURCE_UNITS.overview]}]},
    {id:'market-failure-monopoly',title:'垄断',blocks:[{type:'list',label:'垄断与市场失灵',items:['垄断的含义：','垄断指在生产集中和资本集中高度发展的基础上，一个大企业或少数几个大企业对相应部门产品生产和销售的独占或联合控制。','垄断导致市场失灵：','在垄断市场上，垄断企业控制产品供给，并通过调节产量而在相当大程度上影响价格。因此，市场机制无法正常发生作用，出现市场失灵。','解决方法：','政府对垄断进行限制，如限制垄断价格和制定反垄断法。'],subsections:[{headingIndex:0,childIndexes:[1]},{headingIndex:2,childIndexes:[3]},{headingIndex:4,childIndexes:[5]}],highlights:['独占或联合控制','控制产品供给','调节产量','影响价格','限制垄断价格','反垄断法'],sourceUnitIds:[MARKET_FAILURE_FACTORS_SOURCE_UNITS.monopoly]}]},
    {id:'market-failure-externality',title:'外部性',blocks:[{type:'list',label:'外部性与市场失灵',items:['外部性的含义：','外部影响又称外部性，指某种经济活动给与这项活动无关的第三方带来的影响。','外部性的分类：','外部性可以分为正外部性和负外部性。','正外部性指某种经济活动给与这项活动无关的第三方带来的利益。','负外部性指某种经济活动给与这项活动无关的第三方带来的成本。','外部性导致市场失灵：','资源配置的最优应当是单个经济单位从其经济行为中产生的私人成本和私人收益被看成就等于该行为所造成的社会成本和社会收益。','负外部性导致市场失灵：','一个生产者或消费者采取的行动使他人付出了代价但却未给他人补偿，在这种情况下，未给他人的补偿将由社会负担，导致社会成本提高，但社会成本的提高未带来社会收益的增加，社会收益依然与私人收益相等，这就造成了社会成本大于社会收益，资源未实现最优配置。','解决方案：一般由政府向引起负外部性的生产者征收税收，把引起负外部性的外部成本转给引起负外部性的生产者。','正外部性导致市场失灵：','一个生产者或消费者采取的行动对他人产生了有利影响但自己却未获得收益，在这种情况下，该生产者或消费者带来的社会收益大于私人收益，而社会收益增加的成本却依然由私人负担，这就造成了私人成本大于私人收益，资源未实现最优配置。','解决方案：一般由政府向引起正外部性的生产者给予补贴，即把引起正外部性的外部收益转给引起正外部性的生产者。'],subsections:[{headingIndex:0,childIndexes:[1]},{headingIndex:2,childIndexes:[3,4,5]},{headingIndex:6,childIndexes:[7]},{headingIndex:8,childIndexes:[9,10]},{headingIndex:11,childIndexes:[12,13]}],highlights:['正外部性','负外部性','社会成本大于社会收益','征收税收','社会收益大于私人收益','私人成本大于私人收益','给予补贴'],sourceUnitIds:[MARKET_FAILURE_FACTORS_SOURCE_UNITS.externality]}]},
    {id:'market-failure-public-goods',title:'公共物品',blocks:[{type:'list',label:'公共物品与市场失灵',items:['公共物品的含义：','公共物品是指公共使用或消费的物品，严格意义上的公共物品具有非竞争性和非排他性。','补充：私人物品具有竞争性和排他性。','公共物品分为纯公共物品和准公共物品。纯公共物品兼具非竞争性和非排他性。准公共物品只具有其中一个特性，另一个特性表现不充分。','公共物品导致市场失灵：','公共物品的非排他性和非竞争性决定了人们不用购买仍可进行消费（搭便车），公共物品就不会进入市场交易，从而也没有价格，生产者也不愿意向社会提供。市场调节无法提供充分的公共物品，就出现了无效率的资源配置。','公共物品的解决方案：','在市场经济中，主要由政府来提供公共物品。'],subsections:[{headingIndex:0,childIndexes:[1,2,3]},{headingIndex:4,childIndexes:[5]},{headingIndex:6,childIndexes:[7]}],highlights:['非竞争性','非排他性','竞争性','排他性','纯公共物品','准公共物品','搭便车','政府'],sourceUnitIds:[MARKET_FAILURE_FACTORS_SOURCE_UNITS.publicGoods]}]},
    {id:'market-failure-information',title:'信息不对称',blocks:[{type:'list',label:'信息不对称与市场失灵',items:['信息不对称的含义：','信息不对称，又称信息不完全，是指交易中的个人拥有的信息不同。','信息不对称导致市场失灵：','逆向选择是指在买卖双方信息不对称的情况下，差的商品总是将好的商品驱逐出市场，即优汰劣胜。逆向选择通常发生在事前。（补充：劣币驱逐良币）','道德风险是指在双方信息不对称的情况下，从事经济活动的人在最大限度地增进自身效用的同时做出不利于他人的行动。道德风险多发生在事后。','信息不对称的解决方案：','通过政府在信息方面进行调控，以保证消费者和生产者能够得到充分和正确的信息，以便做出正确的选择。'],subsections:[{headingIndex:0,childIndexes:[1]},{headingIndex:2,childIndexes:[3,4]},{headingIndex:5,childIndexes:[6]}],highlights:['信息不完全','逆向选择','事前','劣币驱逐良币','道德风险','事后','充分和正确的信息'],sourceUnitIds:[MARKET_FAILURE_FACTORS_SOURCE_UNITS.asymmetry]}]},
  ]});

  const macroGoalsOverviewPoint=(points||[]).find((item)=>item.id==='macro-control-goals-overview');
  if(macroGoalsOverviewPoint) Object.assign(macroGoalsOverviewPoint,{categoryId:'macro-control-goals',title:'宏观调控的目标',summary:'承接节标题后的直接正文，完整保留四项目标总览。',preview:'促进经济增长；增加就业；稳定物价；保持国际收支平衡',keywords:['促进经济增长','增加就业','稳定物价','国际收支平衡'],aliases:['两增一稳保平衡'],tags:['常识判断','经济常识','宏观经济学'],indexText:'宏观调控目标总览无编号小节。',sourceSections:[14],sourceUnitIds:[MACRO_GOALS_OVERVIEW_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'四项目标记作“两增一稳保平衡”：经济增长、增加就业、稳定物价、国际收支平衡，其中经济增长最主要。',focus:[{label:'宏观调控的四项目标',note:'宏观调控追求促进经济增长、增加就业、稳定物价、保持国际收支平衡，促进经济增长是最主要目标。',sourceUnitIds:[MACRO_GOALS_OVERVIEW_SOURCE_UNITS.overview]}],route:['目标总览'],review:['宏观调控有四项目标。','两增：促进经济增长、增加就业。','一稳：稳定物价；一平衡：保持国际收支平衡。','最主要目标：促进经济增长。']},tabs:[{id:'macro-goals-overview',title:'目标总览',blocks:[{type:'list',label:'宏观调控的四项目标',items:['宏观调控的目标主要有促进经济增长、增加就业、稳定物价、保持国际收支平衡，其中，促进经济增长是宏观调控最主要的目标。（两增一稳保平衡）'],highlights:['促进经济增长','增加就业','稳定物价','保持国际收支平衡','最主要的目标'],sourceUnitIds:[MACRO_GOALS_OVERVIEW_SOURCE_UNITS.overview]}]}]});

  const economicGrowthPoint=(points||[]).find((item)=>item.id==='economic-growth');
  if(economicGrowthPoint) Object.assign(economicGrowthPoint,{categoryId:'macro-control-goals',title:'经济增长',summary:'按含义、三驾马车、GDP、GNP 4个知识点完整重建。',preview:'产品劳务总量扩大；投资消费出口；GDP地域；GNP国民',keywords:['经济增长','三驾马车','投资','消费','出口','GDP','GNP','最终产品','流量','地域概念','国民概念'],aliases:['国内生产总值','国民生产总值'],tags:['常识判断','经济常识','宏观经济学'],indexText:'经济增长小节含含义、三驾马车、GDP与GNP。',sourceSections:[14,15],sourceUnitIds:[ECONOMIC_GROWTH_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'先认定增长是产品和劳务总量扩大，再记投资、消费、出口三驾马车；核算时用“境内生产”识别GDP的地域口径，用“常住居民要素”识别GNP的国民口径。',focus:[
    {label:'经济增长的含义',note:'一国一定时期产品与劳务总量扩大，表现为GDP总量或人均量增加。',sourceUnitIds:[ECONOMIC_GROWTH_SOURCE_UNITS.meaning]},
    {label:'拉动经济增长的三驾马车',note:'投资、消费、出口是最主要动力；投资和消费合称内需，出口属于外需。',sourceUnitIds:[ECONOMIC_GROWTH_SOURCE_UNITS.drivers]},
    {label:'国内生产总值（GDP）',note:'GDP按地域核算一定时期境内生产的最终产品市场价值，强调市场价值、最终产品、生产而非售出、流量、市场活动和地域口径。',sourceUnitIds:[ECONOMIC_GROWTH_SOURCE_UNITS.gdp]},
    {label:'国民生产总值（GNP）',note:'GNP按国民口径核算常住居民所拥有生产要素生产的全部最终产品市场价值，与GDP的地域口径相区别。',sourceUnitIds:[ECONOMIC_GROWTH_SOURCE_UNITS.gnp]},
  ],route:['增长含义','三驾马车','GDP','GNP'],review:['经济增长：一定时期产品和劳务总量扩大，表现为GDP总量或人均量增加。','三驾马车：投资、消费、出口；投资和消费是内需，出口是外需。','GDP只计最终产品，按生产而非售出计算，是流量、市场活动和地域概念。','GDP不计中间产品价值以及家务劳动、自给自足等非市场活动。','GNP以常住居民及其生产要素为口径，是国民概念；GDP是地域概念。']},tabs:[
    {id:'economic-growth-meaning',title:'增长含义',blocks:[{type:'list',label:'经济增长的含义',items:['一国一定时期内生产的产品和提供的劳务总量的扩大，表现为GDP总量或人均量的增加。'],highlights:['一定时期','产品','劳务总量的扩大','GDP总量或人均量'],sourceUnitIds:[ECONOMIC_GROWTH_SOURCE_UNITS.meaning]}]},
    {id:'economic-growth-drivers',title:'三驾马车',blocks:[{type:'list',label:'拉动经济增长的三驾马车',items:['“三驾马车”是指投资、消费和出口，它们是拉动经济增长的最主要力量。','投资和消费合称为内需，出口称为外需。'],highlights:['投资','消费','出口','内需','外需'],sourceUnitIds:[ECONOMIC_GROWTH_SOURCE_UNITS.drivers]}]},
    {id:'economic-growth-gdp',title:'GDP',blocks:[{type:'list',label:'国内生产总值（GDP）',items:['国内生产总值（GDP），指经济社会（即一国或一地区）在一定时期内运用生产要素所生产的全部最终产品（物品和劳务）的市场价值。','GDP的核算要点：','GDP是一个市场价值的概念。产品市场价值即用这些最终产品的单位价格乘以产量获得。','GDP测度的是最终产品的价值，中间产品价值不计入GDP，否则会造成重复计算。','GDP是一定时期内（往往为一年）所生产而不是所售卖掉的最终产品价值。','GDP是计算期内生产的最终产品价值，因而是流量而不是存量。流量是一定时期内发生的变量，存量是一定时点上存在的变量。','GDP一般仅指市场活动导致的价值。家务劳动、自给自足生产等非市场活动不计入GDP。','GDP是一国范围内生产的最终产品的市场价值，从而是一个地域概念。'],subsections:[{headingIndex:1,childIndexes:[2,3,4,5,6,7]}],highlights:['市场价值','最终产品','中间产品价值不计入','生产','流量而不是存量','非市场活动不计入','地域概念'],sourceUnitIds:[ECONOMIC_GROWTH_SOURCE_UNITS.gdp]}]},
    {id:'economic-growth-gnp',title:'GNP',blocks:[{type:'list',label:'国民生产总值（GNP）',items:['国民生产总值（GNP）是指一个国家或一个地区的常住居民在一定时期所拥有的生产要素所生产的全部最终产品（包括商品和服务）的市场价值。','国内生产总值是一个地域概念，而国民生产总值是一个国民概念。'],highlights:['常住居民','生产要素','最终产品','市场价值','地域概念','国民概念'],sourceUnitIds:[ECONOMIC_GROWTH_SOURCE_UNITS.gnp]}]},
  ]});

  const fullEmploymentPoint=(points||[]).find((item)=>item.id==='full-employment');
  if(fullEmploymentPoint) Object.assign(fullEmploymentPoint,{categoryId:'macro-control-goals',title:'充分就业',summary:'按就业衡量、失业含义、失业类型、相关概念4个知识点完整重建。',preview:'失业率；摩擦结构季节周期；自愿非自愿；自然失业率；充分就业',keywords:['失业率','失业','摩擦性失业','结构性失业','季节性失业','周期性失业','自愿失业','非自愿失业','自然失业率','充分就业'],aliases:['就业状况'],tags:['常识判断','经济常识','宏观经济学'],indexText:'充分就业小节含衡量、失业定义和类型、相关概念4个知识点。',sourceSections:[15,16],sourceUnitIds:[FULL_EMPLOYMENT_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'就业先看失业率；类型按“原因”分摩擦、结构、季节、周期，按“意愿”分自愿、非自愿；充分就业不是零失业，而是实际失业率等于自然失业率。',focus:[
    {label:'就业状况的衡量',note:'实际统计中，一般用失业率衡量一国就业状况。',sourceUnitIds:[FULL_EMPLOYMENT_SOURCE_UNITS.measure]},
    {label:'失业的含义',note:'失业者须达到就业年龄、有劳动能力、愿意就业且没有工作。',sourceUnitIds:[FULL_EMPLOYMENT_SOURCE_UNITS.unemploymentMeaning]},
    {label:'失业的类型',note:'按原因分摩擦、结构、季节、周期性失业；按意愿分自愿和非自愿失业。',sourceUnitIds:[FULL_EMPLOYMENT_SOURCE_UNITS.types]},
    {label:'失业的相关概念',note:'失业率是失业人口与劳动力人口之比；自然失业包括摩擦和结构性失业；充分就业是实际失业率等于自然失业率，并非零失业。',sourceUnitIds:[FULL_EMPLOYMENT_SOURCE_UNITS.concepts]},
  ],route:['就业衡量','失业含义','失业类型','相关概念'],review:['一国就业状况通常以失业率衡量。','失业的三个条件：有劳动能力、愿意就业、没有工作。','按原因：摩擦、结构、季节、周期性失业；按意愿：自愿、非自愿失业。','失业率＝失业人口／劳动力人口；自然失业通常包括摩擦性和结构性失业。','充分就业：实际失业率等于自然失业率，不代表失业率为零。']},tabs:[
    {id:'employment-measure',title:'就业衡量',blocks:[{type:'list',label:'就业状况的衡量',items:['在实际统计中，一般用失业率来衡量一国的就业状况。'],highlights:['失业率','就业状况'],sourceUnitIds:[FULL_EMPLOYMENT_SOURCE_UNITS.measure]}]},
    {id:'unemployment-meaning',title:'失业含义',blocks:[{type:'list',label:'失业的含义',items:['失业即主体达到就业年龄，具备工作能力，谋求工作但仍未得到就业机会的状态。','失业主体必须具备的三个条件：有劳动能力；愿意就业；没有工作。'],highlights:['达到就业年龄','具备工作能力','谋求工作','未得到就业机会','有劳动能力','愿意就业','没有工作'],sourceUnitIds:[FULL_EMPLOYMENT_SOURCE_UNITS.unemploymentMeaning]}]},
    {id:'unemployment-types',title:'失业类型',blocks:[{type:'list',label:'失业的类型',items:['按失业的原因：','摩擦性失业是指劳动者在正常流动过程中所产生的失业。','结构性失业是指在经济结构的变化过程中，由于劳动力的供给和对劳动力需求在职业、技能、产业、地区分布等方面的不一致所引起的失业。','季节性失业是指由于季节变化而产生的失业。','周期性失业是指在经济周期中的衰退或萧条阶段因需求下降而造成的失业。','按就业意愿：','自愿失业是指工人不愿意接受现行的工作条件和收入水平而未被雇用而造成的失业。','非自愿失业是指有劳动能力、愿意接受现行工资水平但仍然找不到工作的现象。'],subsections:[{headingIndex:0,childIndexes:[1,2,3,4]},{headingIndex:5,childIndexes:[6,7]}],highlights:['摩擦性失业','结构性失业','季节性失业','周期性失业','自愿失业','非自愿失业'],sourceUnitIds:[FULL_EMPLOYMENT_SOURCE_UNITS.types]}]},
    {id:'unemployment-concepts',title:'相关概念',blocks:[{type:'list',label:'失业的相关概念',items:['失业率：','即失业人口与劳动力人口（在法定年龄范围内，有劳动能力，并正在积极寻找工作的人）之比，是测度失业最常见的指标。','自然失业：','指由于经济中某些难以避免的原因所引起的失业，这种情况下劳动市场处于供求稳定状态。通常包括摩擦性失业和结构性失业两种。','自然失业率：','即自然失业人口与总劳动力人口的比率。','充分就业：','当实际失业率等于自然失业率时的社会就业状况。在这种状态下，国家处于长期均衡状态，所有经济资源均得到充分利用。经济学家一般认为充分就业是自然失业率维持在5%左右。','补充：充分就业不代表失业率为0。'],subsections:[{headingIndex:0,childIndexes:[1]},{headingIndex:2,childIndexes:[3]},{headingIndex:4,childIndexes:[5]},{headingIndex:6,childIndexes:[7,8]}],highlights:['失业人口','劳动力人口','摩擦性失业','结构性失业','实际失业率','自然失业率','5%左右','不代表失业率为0'],sourceUnitIds:[FULL_EMPLOYMENT_SOURCE_UNITS.concepts]}]},
  ]});

  const stablePricesPoint=(points||[]).find((item)=>item.id==='stable-prices');
  if(stablePricesPoint) Object.assign(stablePricesPoint,{categoryId:'macro-control-goals',title:'稳定物价',summary:'按目标、通货膨胀、衡量指标、再分配效应、通货紧缩5个知识点完整重建。',preview:'抑制通胀；CPI/PPI/WPI；固定收入；债权债务；通缩',keywords:['稳定物价','通货膨胀','货币超发','CPI','PPI','WPI','固定收入','债权人','债务人','通货紧缩'],aliases:['物价稳定'],tags:['常识判断','经济常识','宏观经济学'],indexText:'稳定物价小节含目标、通胀、指标、再分配与通缩5个知识点。',sourceSections:[16,17],sourceUnitIds:[STABLE_PRICES_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'稳定物价就是抑制通胀、避免通缩并维持币值；通胀看货币供给过大与总需求大于总供给，指标重点区分CPI、PPI、WPI，再记通胀不利固定收入者与债权人。',focus:[
    {label:'稳定物价的目标',note:'稳定物价是抑制通货膨胀、避免通货紧缩、维持币值稳定。',sourceUnitIds:[STABLE_PRICES_SOURCE_UNITS.overview]},
    {label:'通货膨胀的含义',note:'货币供给超过实际需求、现实购买力大于产出供给，导致货币贬值和商品劳务价格持续普遍上涨；实质是总需求大于总供给，直接原因是货币超发。',sourceUnitIds:[STABLE_PRICES_SOURCE_UNITS.inflation]},
    {label:'衡量通货膨胀程度的指标',note:'通胀率衡量严重程度；CPI反映居民生活产品劳务价格，PPI反映原材料和中间投入品价格，WPI反映批发价格变化。',sourceUnitIds:[STABLE_PRICES_SOURCE_UNITS.indicators]},
    {label:'通货膨胀的再分配效应',note:'通胀不利于固定货币收入者和债权人，有利于变动收入者和债务人。',sourceUnitIds:[STABLE_PRICES_SOURCE_UNITS.redistribution]},
    {label:'通货紧缩',note:'通货紧缩是一般物价水平持续下降，实质是社会总供给大于社会总需求。',sourceUnitIds:[STABLE_PRICES_SOURCE_UNITS.deflation]},
  ],route:['稳定目标','通货膨胀','衡量指标','再分配效应','通货紧缩'],review:['稳定物价：抑制通货膨胀、避免通货紧缩、维持币值稳定。','通胀：货币供给超过实际需求，价格持续普遍上涨；实质为总需求大于总供给。','CPI看居民生活价格，PPI看原材料和中间投入品价格，WPI看批发价格。','通胀不利固定收入者、债权人；有利变动收入者、债务人。','通缩：一般物价持续下降，实质为总供给大于总需求。']},tabs:[
    {id:'stable-prices-overview',title:'稳定目标',blocks:[{type:'list',label:'稳定物价的目标',items:['稳定物价即抑制通货膨胀、避免通货紧缩、维持币值的稳定。'],highlights:['抑制通货膨胀','避免通货紧缩','维持币值的稳定'],sourceUnitIds:[STABLE_PRICES_SOURCE_UNITS.overview]}]},
    {id:'stable-prices-inflation',title:'通货膨胀',blocks:[{type:'list',label:'通货膨胀的含义',items:['通货膨胀，是指在货币流通条件下，因货币供给大于货币实际需求，也即现实购买力大于产出供给，导致货币贬值，而引起的一段时间内商品和劳务的价格持续而普遍地上涨现象。其实质是社会总需求大于社会总供给。','补充：引起通货膨胀的直接原因是货币超发（货币供给大于货币实际需求）。'],highlights:['货币供给大于货币实际需求','现实购买力大于产出供给','货币贬值','持续而普遍地上涨','社会总需求大于社会总供给','货币超发'],sourceUnitIds:[STABLE_PRICES_SOURCE_UNITS.inflation]}]},
    {id:'stable-prices-indicators',title:'衡量指标',blocks:[{type:'list',label:'衡量通货膨胀程度的指标',items:['衡量：','通货膨胀的严重程度是通过通货膨胀率这一指标来衡量的。','消费价格指数（CPI）：','消费价格指数（CPI）是用与居民生活有关的产品及劳务价格统计出来的物价变动指标，通常作为观察通货膨胀水平的重要指标。','补充：CPI涨幅＞3%是通货膨胀，CPI涨幅＞5%是严重通货膨胀，CPI涨幅＜1%是通货紧缩。','生产价格指数（PPI）：','生产价格指数（PPI）是衡量原材料和中间投入品等价格平均水平的价格指数，是对给定的一组商品的成本的度量。','批发物价指数（WPI）：','通货膨胀测定指标的一种，是根据商品批发价格变动资料所编制，反映不同时期生产资料和消费品批发价格的变动趋势与幅度的相对数。'],subsections:[{headingIndex:0,childIndexes:[1]},{headingIndex:2,childIndexes:[3,4]},{headingIndex:5,childIndexes:[6]},{headingIndex:7,childIndexes:[8]}],highlights:['通货膨胀率','CPI','居民生活','＞3%','＞5%','＜1%','PPI','原材料','中间投入品','WPI','批发价格'],sourceUnitIds:[STABLE_PRICES_SOURCE_UNITS.indicators]}]},
    {id:'stable-prices-redistribution',title:'再分配效应',blocks:[{type:'list',label:'通货膨胀的再分配效应',items:['其一，通货膨胀不利于靠固定的货币收入维持生活的人。相反，那些靠变动收入维持生活的人则会从通货膨胀中得益。','其二，通货膨胀不利于债权人，有利于债务人。'],highlights:['固定的货币收入','变动收入','不利于债权人','有利于债务人'],sourceUnitIds:[STABLE_PRICES_SOURCE_UNITS.redistribution]}]},
    {id:'stable-prices-deflation',title:'通货紧缩',blocks:[{type:'list',label:'通货紧缩',items:['通货紧缩是指一般物价水平持续下降的一种货币现象。其实质是社会总供给大于社会总需求。'],highlights:['一般物价水平持续下降','社会总供给大于社会总需求'],sourceUnitIds:[STABLE_PRICES_SOURCE_UNITS.deflation]}]},
  ]});

  const balanceOfPaymentsPoint=(points||[]).find((item)=>item.id==='balance-of-payments');
  if(balanceOfPaymentsPoint) Object.assign(balanceOfPaymentsPoint,{categoryId:'macro-control-goals',title:'国际收支平衡',summary:'完整保留国际收支平衡定义及净出口、净资本流出计算式。',preview:'净出口；净资本流出；差额为零',keywords:['国际收支平衡','国际收支净额','净出口','净资本流出','出口','进口'],aliases:['国际收支'],tags:['常识判断','经济常识','宏观经济学'],indexText:'国际收支平衡小节含定义和两个计算式。',sourceSections:[17],sourceUnitIds:[BALANCE_OF_PAYMENTS_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'国际收支平衡的判断是“净出口与净资本流出的差额为零”；计算时净出口看出口减进口，净资本流出看本国居民购买外国资产减外国人购买本国资产。',focus:[{label:'国际收支平衡的含义与计算',note:'一国国际收支净额即净出口与净资本流出的差额为零；净出口＝出口－进口，净资本流出＝本国居民购买外国资产－外国人购买本国资产。',sourceUnitIds:[BALANCE_OF_PAYMENTS_SOURCE_UNITS.meaning]}],route:['定义与计算'],review:['国际收支平衡：净出口与净资本流出的差额为零。','净出口＝出口－进口。','净资本流出＝本国居民购买外国资产－外国人购买本国资产。']},tabs:[{id:'balance-of-payments-meaning',title:'定义与计算',blocks:[{type:'list',label:'国际收支平衡的含义与计算',items:['国际收支平衡，指一国国际收支净额即净出口与净资本流出的差额为零。','净出口＝出口—进口。','净资本流出＝本国居民购买的外国资产—外国人购买的本国资产。'],highlights:['差额为零','净出口','出口—进口','净资本流出','本国居民购买的外国资产','外国人购买的本国资产'],sourceUnitIds:[BALANCE_OF_PAYMENTS_SOURCE_UNITS.meaning]}]}]});

  const macroControlMeasuresPoint=(points||[]).find((item)=>item.id==='macro-control-measures');
  if(macroControlMeasuresPoint) Object.assign(macroControlMeasuresPoint,{categoryId:'macro-economic-policies',title:'宏观调控的手段',summary:'以经济、法律、行政3种手段及其适用次序完整重建。',preview:'财政货币；经济法规；行政命令；经济法律为主',keywords:['经济手段','财政政策','货币政策','法律手段','经济法规','行政手段','行政命令'],aliases:['宏观调控工具'],tags:['常识判断','经济常识','宏观经济学'],indexText:'宏观调控手段小节含经济、法律、行政手段及主辅关系。',sourceSections:[17],sourceUnitIds:[MACRO_CONTROL_MEASURES_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'宏观调控有经济、法律、行政三种手段：财政货币属于经济手段，法规属于法律手段，命令指示属于行政手段；原则上以经济和法律为主，必要行政为辅。',focus:[{label:'宏观调控的三种手段',note:'经济手段以财政、货币政策为主，法律手段靠经济法规，行政手段以强制命令等调节；总体上经济和法律为主、必要行政为辅。',sourceUnitIds:[MACRO_CONTROL_MEASURES_SOURCE_UNITS.measures]}],route:['三种手段'],review:['经济手段：财政政策、货币政策，还可用发展战略规划、收入分配政策、产业政策引导。','法律手段：制定和运用经济法规调节宏观经济。','行政手段：强制性的命令、指示、规定、指标、禁止、整顿等。','宏观调控以经济和法律手段为主，辅以必要行政手段。']},tabs:[{id:'macro-control-measures',title:'三种手段',blocks:[{type:'list',label:'宏观调控的三种手段',items:['经济手段：','财政政策和货币政策是国家在宏观调控中最常用的经济手段。国家还可以通过制定和实施经济发展战略和规划、收入分配政策、产业政策等，对经济活动参与者进行引导，以实现国民经济持续健康发展。','法律手段：','国家通过制定和运用经济法规等，影响和调节宏观经济，促进国民经济持续健康发展。','行政手段：','国家通过采取具有强制性的行政命令、指示等行政手段，影响和调节宏观经济，促进国民经济持续健康发展。主要包括行政命令、指示、规定、指标、禁止、整顿等。','手段的主辅关系：','宏观调控应该以经济手段和法律手段为主，辅之以必要的行政手段，形成科学的调控体系，充分发挥宏观调控手段的总体功能。'],subsections:[{headingIndex:0,childIndexes:[1]},{headingIndex:2,childIndexes:[3]},{headingIndex:4,childIndexes:[5]},{headingIndex:6,childIndexes:[7]}],highlights:['财政政策','货币政策','经济法规','强制性','行政命令','经济手段和法律手段为主','必要的行政手段'],sourceUnitIds:[MACRO_CONTROL_MEASURES_SOURCE_UNITS.measures]}]}]});

  const fiscalPolicyPoint=(points||[]).find((item)=>item.id==='fiscal-policy');
  if(fiscalPolicyPoint) Object.assign(fiscalPolicyPoint,{categoryId:'macro-economic-policies',title:'财政政策',summary:'按定义预算、财政收入、财政支出、政策运用4个知识点完整重建。',preview:'自动稳定器；税利债费；购买与转移支付；通缩扩张通胀紧缩',keywords:['财政政策','财政预算','财政赤字','财政盈余','税','利','债','费','政府购买','转移支付','扩张性财政政策','紧缩性财政政策'],aliases:['自动稳定器','内在稳定器'],tags:['常识判断','经济常识','宏观经济学'],indexText:'财政政策小节含定义预算、收入支出与扩张紧缩运用。',sourceSections:[17,18,19],sourceUnitIds:[FISCAL_POLICY_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'财政政策以预算和税收调节总供求；先区分收入“税利债费”和支出“政府购买、转移支付”，再按形势反向调节：通缩时减税、增债、增支，通胀时增税、减债、减支。',focus:[
    {label:'财政政策的定义与财政预算',note:'财政政策通过预算、税收及国民收入分配再分配实现总供求平衡，又称自动或内在稳定器；预算有赤字和盈余。',sourceUnitIds:[FISCAL_POLICY_SOURCE_UNITS.definition]},
    {label:'财政收入',note:'财政收入包括税、利、债、费；税收具有强制、无偿、固定性；政策实施主要调整税收和国债。',sourceUnitIds:[FISCAL_POLICY_SOURCE_UNITS.income]},
    {label:'财政支出',note:'财政支出分政府购买和转移支付：前者有实际商品劳务交易并直接形成需求，后者无相应交换，是非购买当年商品劳务的货币支付。',sourceUnitIds:[FISCAL_POLICY_SOURCE_UNITS.spending]},
    {label:'财政政策的运用',note:'经济萧条、通缩时用扩张性财政政策：减税、增发国债、增加财政支出；经济过热、通胀时用紧缩性政策：增税、减少国债、减少支出。',sourceUnitIds:[FISCAL_POLICY_SOURCE_UNITS.application]},
  ],route:['定义与预算','财政收入','财政支出','政策运用'],review:['财政政策通过预算、税收和收入分配再分配，实现总供给与总需求平衡；又称自动稳定器、内在稳定器。','财政预算：赤字为支出＞收入，盈余为收入＞支出。','财政收入包括税、利、债、费；税收强制、无偿、固定，政策主要调税和国债。','财政支出：政府购买有实际交易并直接形成需求；转移支付没有相应商品劳务交换。','通缩：减税、增发国债、增加支出；通胀：增税、减少国债、减少支出。']},tabs:[
    {id:'fiscal-definition',title:'定义与预算',blocks:[{type:'list',label:'财政政策的定义与财政预算',items:['财政政策是指政府运用国家预算和税收等财政手段，通过对国民收入的分配和再分配，来实现社会总供给和社会总需求平衡的一种经济政策。财政政策被称为“自动稳定器”，亦是“内在稳定器”。','知识链接·财政预算：','财政预算包括财政赤字（财政支出＞财政收入）和财政盈余（财政收入＞财政支出）。'],subsections:[{headingIndex:1,childIndexes:[2]}],highlights:['国家预算','税收','分配和再分配','社会总供给','社会总需求','自动稳定器','财政赤字','财政盈余'],sourceUnitIds:[FISCAL_POLICY_SOURCE_UNITS.definition]}]},
    {id:'fiscal-income',title:'财政收入',blocks:[{type:'list',label:'财政收入',items:['财政收入：','财政收入，是指政府为履行其职能、实施公共政策和提供公共物品与服务需要而筹集的一切资金的总和。主要包括税、利、债、费四个部分。','税：','指税收，它是国家为了实现其职能，按照法律预先规定的标准，强制地、无偿地取得财政收入的一种手段。','税收具有强制性、无偿性和固定性三个特征，因此，税收是政府收入中最主要的部分。','利：','指利润，是国家凭借国有资产所有权获得的利润、租金、股息、红利、资金使用费等收入的总称。','债：','指公债，是政府对公众的债务，或公众对政府的债权。它是政府财政收入的另一个组成部分，到期必须还本付息。','公债包括中央政府的债务与地方政府的债务。一般把中央政府的债务称为国债。','补充：国家发行国债的目的是为了把社会上的闲散资金收集起来然后去投资搞基础设施建设。','费：','指费用，是国家政府机关或事业单位在提供公共服务、实施行政管理或提供特定公共设施的使用时，向受益人收取一定费用的收入形式。','实施：','财政政策的实施主要通过调整税收和国债来进行。'],subsections:[{headingIndex:0,childIndexes:[1]},{headingIndex:2,childIndexes:[3,4]},{headingIndex:5,childIndexes:[6]},{headingIndex:7,childIndexes:[8,9,10]},{headingIndex:11,childIndexes:[12]},{headingIndex:13,childIndexes:[14]}],highlights:['税、利、债、费','强制性','无偿性','固定性','国有资产所有权','公债','国债','基础设施建设','调整税收和国债'],sourceUnitIds:[FISCAL_POLICY_SOURCE_UNITS.income]}]},
    {id:'fiscal-spending',title:'财政支出',blocks:[{type:'list',label:'财政支出',items:['财政支出：','财政支出是指通过国家预算安排用于各方面的支出。','按经济性质划分，财政支出分为政府购买和政府转移支付。','政府购买：','政府对商品和劳务的购买，涉及各种项目，包括购买军需品、警察装备用品、政府机关办公用品、付给政府雇员的酬金、各种公共工程项目的支出等。','这是一种实质性支出，有着商品和劳务的实际交易，因而直接形成社会需求和购买力，是国民收入的一个组成部分。','政府转移支付：','政府的社会福利等支出，如卫生保健支出、收入保障支出、退伍军人福利、失业救济和各种补贴等方面的支出。','这是一种货币性支出，政府在付出这些货币时并无相应的商品和劳务的交换，因而是一种不以购买本年的商品和劳务为目的的货币性支付。'],subsections:[{headingIndex:0,childIndexes:[1,2]},{headingIndex:3,childIndexes:[4,5]},{headingIndex:6,childIndexes:[7,8]}],highlights:['政府购买','实质性支出','实际交易','直接形成社会需求和购买力','政府转移支付','货币性支出','无相应交换'],sourceUnitIds:[FISCAL_POLICY_SOURCE_UNITS.spending]}]},
    {id:'fiscal-application',title:'政策运用',blocks:[{type:'table',label:'财政政策的运用',columns:['具体措施','经济萧条（通货紧缩）','经济过热（通货膨胀）'],headerMergedCells:[],rows:[['政策类型','扩张性财政政策','紧缩性财政政策'],['财政收入：税','减少税收','增加税收'],['财政收入：债（主要考虑税和债）','增发国债','减少国债'],['财政支出','增加','减少']],mergedCells:[],mobileLayout:'cards',cardTitleColumn:0,highlights:['扩张性财政政策','紧缩性财政政策','减少税收','增加税收','增发国债','减少国债','增加','减少'],sourceUnitIds:[FISCAL_POLICY_SOURCE_UNITS.application]}]},
  ]});

  const monetaryPolicyPoint=(points||[]).find((item)=>item.id==='monetary-policy');
  if(monetaryPolicyPoint) Object.assign(monetaryPolicyPoint,{categoryId:'macro-economic-policies',title:'货币政策',summary:'按银行制度、定义、工具、政策运用、三率原则5个知识点完整重建。',preview:'央行商行投行政策行；三率与公开市场；三降一买三高一卖',keywords:['中央银行','商业银行','投资银行','政策性银行','货币供应量','存款准备金率','再贴现率','公开市场业务','基准利率','三率统一'],aliases:['三率统一原则'],tags:['常识判断','经济常识','宏观经济学'],indexText:'货币政策小节含银行制度、定义、工具、运用和三率原则。',sourceSections:[19,20],sourceUnitIds:[MONETARY_POLICY_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'先分清央行、商行、投行、政策行，再把货币政策理解为央行调节货币供应量；通缩时“三降一买”，通胀时“三高一卖”，三种利率工具方向一致。',focus:[
    {label:'银行制度',note:'中央银行统筹金融并实施货币政策；商业银行以营利为目的并办理存贷结算；投资银行服务资本市场；政策性银行配合政府政策。',sourceUnitIds:[MONETARY_POLICY_SOURCE_UNITS.banks]},
    {label:'货币政策的定义',note:'中央银行通过控制、调节货币供应量，维持社会总供给和总需求平衡。',sourceUnitIds:[MONETARY_POLICY_SOURCE_UNITS.definition]},
    {label:'货币政策工具',note:'四项工具是法定存款准备金率、再贴现率、公开市场业务和基准利率。',sourceUnitIds:[MONETARY_POLICY_SOURCE_UNITS.tools]},
    {label:'货币政策的运用',note:'通缩用扩张政策：三率降低、买入债券；通胀用紧缩政策：三率提高、卖出债券。',sourceUnitIds:[MONETARY_POLICY_SOURCE_UNITS.application]},
    {label:'三率统一原则',note:'法定存款准备金率、再贴现率、基准利率的调节方向一致。',sourceUnitIds:[MONETARY_POLICY_SOURCE_UNITS.principle]},
  ],route:['银行制度','政策定义','政策工具','政策运用','三率原则'],review:['中央银行是最高金融当局；中国人民银行是我国央行。商业银行基础业务是存款，主体业务和主要利润来源是贷款。','投资银行是资本市场金融中介；我国政策性银行为中国进出口银行、中国农业发展银行。','货币政策由中央银行调节货币供应量以平衡总供求。','通缩：降低三率、买入债券；通胀：提高三率、卖出债券。','三率统一：准备金率、再贴现率、基准利率方向一致。']},tabs:[
    {id:'monetary-banks',title:'银行制度',blocks:[{type:'list',label:'银行制度',items:['中央银行：','中央银行是一国最高金融当局，它统筹管理全国金融活动，实施货币政策以影响经济。我国的中央银行是中国人民银行。','中央银行具有三个职能：作为发行的银行。作为银行的银行。作为国家的银行。','商业银行：','商业银行是一个以营利为目的，以多种金融负债筹集资金，多种金融资产为经营对象，具有信用创造功能的金融机构。','国有商业银行主要包括：中国工商银行、中国农业银行、中国银行、中国建设银行、交通银行、中国邮政储蓄银行。','补充：除了国有商业银行外，还有很多地方性商业银行，比如：锦州银行、沧州银行等。','商业银行的主要业务有三类：','其一，存款业务。这项业务是商业银行的基础业务。','其二，贷款业务。它是商业的主体业务，也是商业银行营利的主要来源。','其三，结算业务。结算业务是商业银行为社会经济活动中发生的货币收支提供手段与工具的服务，银行对此收取一定的服务费用。','投资银行：','投资银行主要从事证券发行、承销、交易、企业重组、兼并与收购、投资分析、风险投资、项目融资等业务的非银行金融机构，是资本市场上的主要金融中介。','政策性银行：','政策性银行是指由政府发起、出资成立，为贯彻和配合政府特定经济政策和意图而进行融资和信用活动的机构。','我国的政策性银行为：中国进出口银行、中国农业发展银行。','注：2015年3月，国务院明确国开行定位为开发性金融机构。'],subsections:[{headingIndex:0,childIndexes:[1,2]},{headingIndex:3,childIndexes:[4,5,6,7]},{headingIndex:7,childIndexes:[8,9,10]},{headingIndex:11,childIndexes:[12]},{headingIndex:13,childIndexes:[14,15,16]}],highlights:['最高金融当局','中国人民银行','发行的银行','银行的银行','国家的银行','存款业务','基础业务','贷款业务','主体业务','投资银行','中国进出口银行','中国农业发展银行','开发性金融机构'],sourceUnitIds:[MONETARY_POLICY_SOURCE_UNITS.banks]}]},
    {id:'monetary-definition',title:'政策定义',blocks:[{type:'list',label:'货币政策的定义',items:['货币政策是指中央银行通过控制和调节货币供应量以保持社会总供给和社会总需求平衡的一种经济政策。'],highlights:['中央银行','控制和调节货币供应量','社会总供给','社会总需求'],sourceUnitIds:[MONETARY_POLICY_SOURCE_UNITS.definition]}]},
    {id:'monetary-tools',title:'政策工具',blocks:[{type:'list',label:'货币政策工具',items:['法定存款准备金率：','法定存款准备金率是指中央银行规定的商业银行对于存款所必须保持的准备金的比例。','再贴现率：','再贴现率是商业银行将其贴现的未到期票据向中央银行申请再贴现时的预扣利率。','公开市场业务：','公开市场业务是指中央银行通过买进或卖出有价证券（主要是政府公债和国库券），吞吐基础货币，调节货币供应量的活动。','基准利率：','基准利率是金融市场上具有普遍参照作用的利率，其他利率水平或金融资产价格均可根据这一基准利率水平来确定。'],subsections:[{headingIndex:0,childIndexes:[1]},{headingIndex:2,childIndexes:[3]},{headingIndex:4,childIndexes:[5]},{headingIndex:6,childIndexes:[7]}],highlights:['法定存款准备金率','再贴现率','公开市场业务','买进或卖出有价证券','基准利率'],sourceUnitIds:[MONETARY_POLICY_SOURCE_UNITS.tools]}]},
    {id:'monetary-application',title:'政策运用',blocks:[{type:'table',label:'货币政策的运用',columns:['政策工具','经济萧条（通货紧缩）','经济过热（通货膨胀）'],headerMergedCells:[],rows:[['政策类型','扩张性货币政策','紧缩性货币政策'],['法定存款准备金率','降低','提高'],['再贴现率','降低','提高'],['公开市场业务','买入债券','卖出债券'],['基准利率','降低','提高']],mergedCells:[],mobileLayout:'cards',cardTitleColumn:0,highlights:['扩张性货币政策','紧缩性货币政策','降低','提高','买入债券','卖出债券'],sourceUnitIds:[MONETARY_POLICY_SOURCE_UNITS.application]}]},
    {id:'monetary-principle',title:'三率原则',blocks:[{type:'list',label:'三率统一原则',items:['补充：三率统一原则：法定存款准备金率、再贴现率、基准利率三者调节方向一致。'],highlights:['法定存款准备金率','再贴现率','基准利率','方向一致'],sourceUnitIds:[MONETARY_POLICY_SOURCE_UNITS.principle]}]},
  ]});

  const industrialPolicyPoint=(points||[]).find((item)=>item.id==='industrial-policy');
  if(industrialPolicyPoint) Object.assign(industrialPolicyPoint,{categoryId:'macro-economic-policies',title:'产业政策',summary:'按产业政策定义、我国产业结构2个知识点完整重建。',preview:'政府干预产业形成发展；农林牧渔；采矿制造建筑；流通服务',keywords:['产业政策','产业结构','第一产业','第二产业','第三产业','农业','制造业','建筑业','流通','服务'],aliases:['三次产业'],tags:['常识判断','经济常识','宏观经济学'],indexText:'产业政策小节含定义与三次产业结构。',sourceSections:[20],sourceUnitIds:[INDUSTRIAL_POLICY_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'产业政策是政府为经济社会目标干预产业形成发展；结构上按“自然力生产—加工生产—流通服务”区分第一、第二、第三产业。',focus:[
    {label:'产业政策的定义',note:'政府为实现经济和社会目标，对产业形成和发展进行干预的各类政策总和。',sourceUnitIds:[INDUSTRIAL_POLICY_SOURCE_UNITS.definition]},
    {label:'我国的产业结构',note:'第一产业包括农林渔牧；第二产业包括采矿、制造、电力燃气及水供应、建筑；第三产业包括流通和服务。',sourceUnitIds:[INDUSTRIAL_POLICY_SOURCE_UNITS.structure]},
  ],route:['政策定义','产业结构'],review:['产业政策：政府为一定经济社会目标，对产业形成和发展进行干预的政策总和。','第一产业主要利用自然力，包括农业、林业、渔业、畜牧业。','第二产业加工原料，包括采矿、制造、电力燃气及水供应、建筑业。','第三产业不生产物质产品，包括流通和服务两大部门。']},tabs:[
    {id:'industrial-definition',title:'政策定义',blocks:[{type:'list',label:'产业政策的定义',items:['产业政策是政府为了实现一定的经济和社会目标而对产业的形成和发展进行干预的各种政策的总和。'],highlights:['经济和社会目标','产业的形成和发展','干预'],sourceUnitIds:[INDUSTRIAL_POLICY_SOURCE_UNITS.definition]}]},
    {id:'industrial-structure',title:'产业结构',blocks:[{type:'list',label:'我国的产业结构',items:['第一产业：','第一产业，又称第一次产业，指以利用自然力为主，生产不必经过深度加工就可消费的产品或工业原料的部门。我国一般包括农业、林业、渔业、畜牧业。','第二产业：','第二产业，指以对第一产业和本产业提供的产品（原料）进行加工的产业部门。我国包括采矿业，制造业，电力、燃气及水的生产和供应业，建筑业。','第三产业：','第三产业，指不生产物质产品的行业，包括流通和服务两大部门。'],subsections:[{headingIndex:0,childIndexes:[1]},{headingIndex:2,childIndexes:[3]},{headingIndex:4,childIndexes:[5]}],highlights:['第一产业','自然力','农业','林业','渔业','畜牧业','第二产业','采矿业','制造业','建筑业','第三产业','流通','服务'],sourceUnitIds:[INDUSTRIAL_POLICY_SOURCE_UNITS.structure]}]},
  ]});

  const incomeDistributionPoint=(points||[]).find((item)=>item.id==='income-distribution-policy');
  if(incomeDistributionPoint) Object.assign(incomeDistributionPoint,{categoryId:'macro-economic-policies',title:'收入分配政策',summary:'按政策总览、三次分配、基尼系数、社会结构4个知识点完整重建。',preview:'最低工资社保税收财政；初次再分配第三次；基尼；橄榄型稳定',keywords:['收入分配政策','最低工资','社会保障','初次分配','再分配','第三次分配','基尼系数','金字塔型','哑铃型','橄榄型'],aliases:['国民收入分配'],tags:['常识判断','经济常识','宏观经济学'],indexText:'收入分配政策小节含政策总览、三次分配、基尼和社会结构。',sourceSections:[21],sourceUnitIds:[INCOME_DISTRIBUTION_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'先看分配主体与目标：初次分配由生产部门和市场重效率，再分配由政府重公平，第三次分配靠自愿慈善；基尼越大越不平等，橄榄型社会最稳定。',focus:[
    {label:'收入分配政策的含义与手段',note:'国家针对收入水平和差距制定原则方针，常用最低工资、社保、税收和公共财政支出。',sourceUnitIds:[INCOME_DISTRIBUTION_SOURCE_UNITS.overview]},
    {label:'国民收入分配',note:'初次分配属微观、由生产部门和市场进行；再分配属宏观、由政府调节公平；第三次分配基于自愿慈善和道德原则。',sourceUnitIds:[INCOME_DISTRIBUTION_SOURCE_UNITS.distribution]},
    {label:'基尼系数',note:'基尼系数在0—1之间，数值越大不平等越高；源文补充接近0.4一般认为较公平。',sourceUnitIds:[INCOME_DISTRIBUTION_SOURCE_UNITS.gini]},
    {label:'三种社会结构',note:'金字塔型和哑铃型对抗明显、属非稳定型；橄榄型两头小中间大，属稳定型。',sourceUnitIds:[INCOME_DISTRIBUTION_SOURCE_UNITS.structures]},
  ],route:['政策总览','三次分配','基尼系数','社会结构'],review:['收入分配政策常用最低工资、社会保障、税收和公共财政支出。','初次分配：生产部门和市场，重效率；再分配：政府以收入税调节，重公平；第三次分配：自愿慈善。','基尼系数0—1，越大越不平等；源文以接近0.4为比较公平。','金字塔型、哑铃型属非稳定结构；橄榄型两头小中间大，属稳定结构。']},tabs:[
    {id:'income-policy-overview',title:'政策总览',blocks:[{type:'list',label:'收入分配政策的含义与手段',items:['收入分配政策是指国家为实现宏观调控总目标和总任务，针对居民收入水平高低、收入差距大小在收入分配方面制定的原则和方针。','常用的手段有最低工资、社会保障体系建设、税收和公共财政支出等。'],highlights:['居民收入水平','收入差距','最低工资','社会保障体系','税收','公共财政支出'],sourceUnitIds:[INCOME_DISTRIBUTION_SOURCE_UNITS.overview]}]},
    {id:'income-distribution-stages',title:'三次分配',blocks:[{type:'list',label:'国民收入分配',items:['国民收入的初次分配：','初次分配属于微观分配行为，主要应由生产部门自主进行，使市场机制对要素价格的形成起到基础性作用，政府通过生产税引导和调节资源的合理配置，以提高经济增长的效率。','补充：初次分配由企业进行，分为三个方面：第一，政府收入（生产税）；第二，企业收入（用于企业再生产）；第三，个人收入（员工工资）。','增值税因为是对于生产环节的增值部分征收税收所以属于初次分配。','国民收入的再分配：','再分配属于宏观分配行为，主要由政府以收入税等形式对各个经济主体的初次分配所得进行调节，着重解决社会发展和社会公平问题。','补充：收入税比如个人所得税，以前的营业税等。','国民收入的第三次分配：','第三次分配是建立在志愿性基础上，以募集、自愿捐赠等慈善公益方式对社会资源和社会财富进行的分派。它依靠“精神力量”，奉行“道德原则”。'],subsections:[{headingIndex:0,childIndexes:[1,2,3]},{headingIndex:4,childIndexes:[5,6]},{headingIndex:7,childIndexes:[8]}],highlights:['微观分配','生产部门','市场机制','生产税','增值税','宏观分配','政府','收入税','社会公平','志愿性','慈善公益','道德原则'],sourceUnitIds:[INCOME_DISTRIBUTION_SOURCE_UNITS.distribution]}]},
    {id:'income-gini',title:'基尼系数',blocks:[{type:'list',label:'基尼系数',items:['基尼系数是1943年美国经济学家阿尔伯特·赫希曼根据洛伦兹曲线所定义的判断收入分配公平程度的指标。基尼系数介于0—1之间，基尼系数越大，表示不平等程度越高。','补充：0.4是一个比较公平的数值，基尼系数接近0.4，一般认为收入分配比较公平。'],highlights:['0—1','越大','不平等程度越高','0.4','比较公平'],sourceUnitIds:[INCOME_DISTRIBUTION_SOURCE_UNITS.gini]}]},
    {id:'income-social-structures',title:'社会结构',blocks:[{type:'list',label:'三种社会结构',items:['“金字塔型”结构：','是绝大多数社会成员处于塔的底部，属于贫困阶层。','“哑铃型”结构：','是两头大中间小，在社会总人口中贫困者和富裕者占多数，但中间阶层则比较弱小。“金字塔型”和“哑铃型”社会结构都呈现明显的阶级或阶层的对抗，因此，属于非稳定型的社会结构。','“橄榄型”结构：','就是两头小中间大，即贫困者和极端富裕者只占社会人口的少数，而绝大多数是处在中间的比较富裕的阶层。','社会结构分层理论认为，“橄榄型”属于稳定型的社会结构。'],subsections:[{headingIndex:0,childIndexes:[1]},{headingIndex:2,childIndexes:[3]},{headingIndex:4,childIndexes:[5,6]}],highlights:['金字塔型','哑铃型','非稳定型','橄榄型','两头小中间大','稳定型'],sourceUnitIds:[INCOME_DISTRIBUTION_SOURCE_UNITS.structures]}]},
  ]});

