  if(npcPoint){
    const npcRows=[
      ['全国人民代表大会','1.性质','—','全国最高的权力机关、立法机关、监督机关。'],
      ['','2.组成','—','（1）由省、自治区、直辖市、特别行政区和军队代表组成；采取地域代表制与职业代表制（军队）相结合，以地域代表制为主。\n（2）代表名额总数不超过3000名；每一少数民族都应有自己的代表，人口特别少的少数民族至少一名代表。'],
      ['','3.任期','—','（1）每届任期5年。\n（2）任期届满两个月以前，全国人大常委会必须完成下届全国人大代表选举。'],
      ['','4.职权','立法权','1.修改宪法：由全国人大常委会或者1/5以上全国人大代表提议，并由全体代表2/3以上多数通过。\n2.监督宪法实施。\n3.制定和修改刑事、民事、国家机构和其他基本法律；法律和其他议案由全体代表过半数通过。'],
      ['','','选举任免权','4.选举国家主席、副主席。\n5.根据国家主席提名决定国务院总理；根据总理提名决定副总理、国务委员、各部部长、各委员会主任、审计长、秘书长。\n6.选举中央军委主席；根据军委主席提名决定军委其他组成人员。\n7.选举最高人民法院院长。\n8.选举最高人民检察院检察长。\n9.选举国家监察委员会主任（新增）。'],
      ['','','重大决定权和审批权','10.审查批准国民经济和社会发展计划及执行情况报告。\n11.审查批准国家预算及执行情况报告。\n12.改变或者撤销全国人大常委会不适当决定。\n13.批准省、自治区、直辖市建置。\n14.决定特别行政区设立及制度。\n15.决定战争和和平问题。\n16.应当由最高国家权力机关行使的其他职权。'],
      ['','补充','—','立法权：修宪制法监实施。（修改宪法：人常五一提修宪，人大全体二三过）\n选举任免权：一会两院三主席。\n重大决定权和审批权：审批计划和预算，改撤常委的决定，批省建置定特区，决定战和与其他。'],
      ['','5.会议制度','—','全国人民代表大会会议每年举行一次，由全国人民代表大会常务委员会召集。'],
      ['','6.工作程序','—','通过法律案及其他议案、选举和罢免国家领导人经过：（1）提出议案；（2）审议议案；（3）表决议案；（4）公布法律、决议。法律议案通过后由国家主席以主席令公布；选举结果及重要议案由全国人大主席团以公告公布或由国家主席以主席令公布。']
    ];
    const standingRows=[
      ['全国人大常委会','1.性质和地位','—','全国人民代表大会的常设机关，在全国人大闭会期间行使最高国家权力；与全国人大是隶属关系。'],
      ['','2.组成','—','由委员长、副委员长若干人、秘书长、委员若干人组成。组成人员不得担任国家行政机关、审判机关、检察机关和监察机关的职务。（补充：专职制 VS 兼职制）'],
      ['','3.任期','—','任期与全国人大相同，即5年；委员长、副委员长连续任职不得超过两届。'],
      ['','4.职权','立法权','1.解释宪法，监督宪法实施。\n2.制定修改全国人大制定法律以外的其他法律；全国人大闭会期间可部分补充修改全国人大制定的法律，但不得抵触基本原则。\n3.解释法律。（补充：解释宪律，修制其他）'],
      ['','','经济监督权','4.全国人大闭会期间，审查批准计划、预算执行中必须作的部分调整方案。\n5.监督国务院、中央军委、国家监察委、最高法院、最高检察院工作。'],
      ['','','立法权','6.撤销国务院同宪法法律抵触的行政法规、决定和命令。\n7.撤销省、自治区、直辖市权力机关同宪法法律行政法规抵触的地方性法规和决议。（补充：有隶属关系可撤可改，无隶属关系只撤不改）'],
      ['','','选举任免权','8.闭会期间根据国务院总理提名决定部长、委员会主任、审计长、秘书长。\n9.闭会期间根据中央军委主席提名决定军委其他组成人员。\n10.根据国家监察委主任提请，任免副主任、委员。\n11.根据最高法院院长提请，任免副院长、审判员、审委会委员和军事法院院长。\n12.根据最高检检察长提请，任免副检察长、检察员、检委会委员和军事检察院检察长，并批准省级检察院检察长任免。\n13.决定驻外全权代表任免。'],
      ['','','决定权','14.决定同外国缔结的条约和重要协定的批准和废除。\n15.规定军人和外交人员衔级制度及其他专门衔级制度。\n16.规定和决定授予国家勋章和荣誉称号。\n17.决定特赦。\n18.闭会期间，遇国家遭武装侵犯或须履行共同防止侵略条约时，决定战争状态宣布。\n19.决定全国总动员或局部动员。\n20.决定全国或个别省、自治区、直辖市进入紧急状态。'],
      ['','','其他','21.全国人民代表大会授予的其他职权。']
    ];
    Object.assign(npcPoint,{categoryId:'constitution-organs',title:'全国人民代表大会及其常务委员会',summary:'按全国人大、全国人大常委会2个父知识点完整重建性质组成任期职权会议程序。',preview:'人大六项内部分项；常委四项内部分项；职权分类和数字门槛',keywords:['全国人民代表大会','全国人大常委会','修宪','基本法律','一会两院三主席','委员长','闭会期间','撤销权','特赦'],aliases:['全国人大及其常委会'],tags:['常识判断','法律常识','宪法','国家机构'],indexText:'全国人大及常委会小节含2个父知识点及其完整内部分项。',sourceSections:[32,33,34,35,36],sourceUnitIds:[NPC_STANDING_COMMITTEE_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'用“人大定根本、常委管日常”对照：全国人大掌修宪、基本法律和最高层人事重大决定；常委会在闭会期间解释宪法法律、制定其他法律、监督一府一委两院并处理连续性事务。',focus:[{label:'全国人民代表大会',note:'按“性质—组成—任期—四类职权—会议—程序”回忆，重点门槛是代表不超3000、任期5年、修宪1/5提议与2/3通过、一般议案过半。',sourceUnitIds:[NPC_STANDING_COMMITTEE_SOURCE_UNITS.npc]},{label:'全国人大常委会',note:'抓常设与闭会期间定位，组成实行专职限制，任期5年且正副委员长不超两届，21项职权按立法监督、任免决定分类。',sourceUnitIds:[NPC_STANDING_COMMITTEE_SOURCE_UNITS.standing]}],route:['全国人民代表大会','全国人大常委会'],review:['全国人大：最高权力、立法、监督机关；代表不超3000，任期5年，每年开会一次。','修宪由全国人大常委会或1/5以上代表提议，全体代表2/3以上通过；一般法律议案过半。','全国人大职权抓“修宪和基本法律、一会两院三主席、计划预算、省级建置特区与战和”。','常委会是全国人大常设机关，闭会期间行使最高国家权力；组成人员不得兼任行政、审判、检察、监察机关职务。','常委会职权抓解释宪法法律、制定其他法律、监督一府一委两院、撤销抵触规范、闭会期间任免与决定事项。']},tabs:[{id:'npc',title:'全国人民代表大会',blocks:[{type:'table',label:'全国人民代表大会',columns:['知识点','内部分项','职权类别','完整内容'],rows:npcRows,mergedCells:[{row:0,column:0,rowSpan:9},{row:3,column:1,rowSpan:3}],mobileLayout:'cards',cardTitleColumn:1,cardGroupColumn:0,highlights:['最高的权力机关','不超过3000名','5年','1/5以上','2/3以上','过半数','一会两院三主席','每年举行一次'],sourceUnitIds:[NPC_STANDING_COMMITTEE_SOURCE_UNITS.npc]}]},{id:'npc-standing-committee',title:'全国人大常委会',blocks:[{type:'table',label:'全国人大常委会',columns:['知识点','内部分项','职权类别','完整内容'],rows:standingRows,mergedCells:[{row:0,column:0,rowSpan:9},{row:3,column:1,rowSpan:6}],mobileLayout:'cards',cardTitleColumn:1,cardGroupColumn:0,highlights:['常设机关','闭会期间','隶属关系','不得担任','5年','不得超过两届','解释宪法','监督一府一委两院','只撤不改','特赦'],sourceUnitIds:[NPC_STANDING_COMMITTEE_SOURCE_UNITS.standing]}]}]});
  }

