  if(stateCouncilPoint){const rows=[['国务院','1.性质和地位','—','即中央人民政府，是最高国家权力机关的执行机关、最高国家行政机关；对全国人大负责并报告工作，闭会期间对全国人大常委会负责并报告工作。'],['','2.组成和任期','—','由总理、副总理若干人、国务委员若干人、各部部长、各委员会主任、审计长、秘书长组成。（补充：无副部长）每届任期同全国人大；总理、副总理、国务委员连续任职不得超过两届。'],['','3.会议制度','—','全体会议由国务院全体成员组成，每半年一次；常务会议由总理、副总理、国务委员、秘书长组成，每周一次。'],['','4.领导制度','—','补充：行政首长负责制。国务院实行总理负责制；各部、各委员会实行部长、主任负责制。'],['','5.职权','立法权','根据宪法和法律，规定行政措施，制定行政法规，发布决定和命令。'],['','','提议权','向全国人民代表大会或者全国人民代表大会常务委员会提出议案。'],['','','领导权','规定各部和各委员会的任务职责，统一领导其工作及不属于各部委的全国性行政工作；统一领导全国地方各级国家行政机关，规定中央和省级行政机关职权的具体划分。'],['','','重大事项决定权','编制和执行国民经济和社会发展计划和国家预算；批准省、自治区、直辖市的区域划分，批准自治州、县、自治县、市的建置和区域划分；决定省、自治区、直辖市范围内部分地区进入紧急状态。']];Object.assign(stateCouncilPoint,{categoryId:'constitution-organs',title:'国务院',summary:'完整重建国务院5项内部结构及四类职权。',preview:'最高行政机关；组成任期；半年与每周；总理负责制；立法提议领导决定',keywords:['中央人民政府','最高国家行政机关','总理负责制','行政首长负责制','全体会议','常务会议','行政法规'],aliases:['国务院'],tags:['常识判断','法律常识','宪法','国家机构'],indexText:'国务院小节含1个父知识点及5项内部分项。',sourceSections:[36,37],sourceUnitIds:[STATE_COUNCIL_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'按“地位—人—会—制—权”串联：先定中央人民政府和最高行政机关，再记组成任期、半年/每周会议频率、总理负责制，最后归纳立法提议领导决定四类职权。',focus:[{label:'国务院',note:'国务院是最高权力机关执行机关和最高行政机关；数字抓任期5年、三类正副领导不超两届、全体会半年一次、常务会每周一次。',sourceUnitIds:[STATE_COUNCIL_SOURCE_UNITS.table]}],route:['国务院'],review:['国务院即中央人民政府，是最高权力机关执行机关、最高国家行政机关。','组成无副部长；任期同全国人大，总理、副总理、国务委员连续任职不超两届。','全体会议全体成员、半年一次；常务会议为总理副总理国务委员秘书长、每周一次。','国务院总理负责制；部委实行部长、主任负责制。','职权分立法、提议、领导、重大事项决定四类。']},tabs:[{id:'state-council',title:'国务院',blocks:[{type:'table',label:'国务院',columns:['知识点','内部分项','职权类别','完整内容'],rows,mergedCells:[{row:0,column:0,rowSpan:8},{row:4,column:1,rowSpan:4}],mobileLayout:'cards',cardTitleColumn:1,cardGroupColumn:0,highlights:['中央人民政府','最高国家行政机关','无副部长','不得超过两届','每半年','每周','总理负责制','行政法规'],sourceUnitIds:[STATE_COUNCIL_SOURCE_UNITS.table]}]}]});}

  const statePresidentPoint=(points||[]).find((item)=>item.id==='state-president-judiciary-supervision');
  if(statePresidentPoint){const rows=[['国家主席','1.性质','—','中华人民共和国主席是我国的国家元首，是我国国家机构的重要组成部分，对外代表中华人民共和国。（边界：宪法直接表述为代表中华人民共和国进行国事活动、接受外国使节。）'],['','2.任职条件和任期','—','国家主席、副主席须：（1）有选举权和被选举权；（2）是中华人民共和国公民；（3）年满45周岁。任期5年。'],['','3.职权','外事权','代表国家进行国事活动；代表国家接受外国使节；根据全国人大常委会决定，宣布批准或废除条约和重要协定。'],['','','公布宣布的权力','公布法律、发布命令；发布特赦令，宣布进入紧急状态、动员令、战争状态等；国务院有关组成人员经全国人大或常委会确定后宣布任免；根据常委会决定派出或召回驻外大使；根据常委会决定授予荣誉奖章和光荣称号。'],['','4.主席职位补缺','—','主席缺位由副主席继任；副主席缺位由全国人大补选；主席、副主席都缺位时由全国人大补选，补选前由全国人大常委会委员长暂时代理主席职位。']];Object.assign(statePresidentPoint,{categoryId:'constitution-organs',title:'国家主席',summary:'完整还原性质、任职条件任期、两类职权和职位补缺。',preview:'国家元首教材概括；45周岁；外事与公布宣布；副主席继任与委员长代理',keywords:['国家主席','45周岁','外事权','主席令','特赦令','副主席继任','委员长代理'],aliases:['中华人民共和国主席'],tags:['常识判断','法律常识','宪法','国家机构'],indexText:'国家主席小节含1个父知识点及4项内部分项。',sourceSections:[1],sourceUnitIds:[STATE_PRESIDENT_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'按“身份—门槛—权力—补缺”回忆：任职三条件锁定45周岁，职权分外事与公布宣布，补缺顺序是主席缺位副主席继任、双缺位委员长暂代。',focus:[{label:'国家主席',note:'记“有选举权的45岁中国公民、任期5年”；职权多依全国人大或常委会决定行使，职位补缺区分继任、补选和暂时代理。',sourceUnitIds:[STATE_PRESIDENT_SOURCE_UNITS.table]}],route:['国家主席'],review:['教材概括国家主席为国家元首；宪法直接表述是代表中华人民共和国进行国事活动、接受外国使节。','任职条件：有选举权和被选举权的中国公民，年满45周岁；任期5年。','职权分外事权与公布宣布权，多项行为须根据全国人大常委会决定。','补缺：主席缺位副主席继任；副主席缺位人大补选；双缺位时补选前由人大常委会委员长暂代。']},tabs:[{id:'state-president',title:'国家主席',blocks:[{type:'table',label:'国家主席',columns:['知识点','内部分项','职权类别','完整内容'],rows,mergedCells:[{row:0,column:0,rowSpan:5},{row:2,column:1,rowSpan:2}],mobileLayout:'cards',cardTitleColumn:1,cardGroupColumn:0,highlights:['国家元首','45周岁','5年','外事权','公布法律','特赦令','副主席继任','委员长暂时代理'],sourceUnitIds:[STATE_PRESIDENT_SOURCE_UNITS.table]}]}]});}

