  if(cmcPoint){const rows=[['中央军委','1.性质地位','中央军事委员会是全国武装力量的领导机关。'],['','2.组成与任期','由主席、副主席若干人、委员若干人组成。每届任期同全国人大，为5年；中央军委主席没有连续任职届数限制。'],['','3.领导体制','中央军委实行主席负责制。中央军委主席对全国人大和全国人大常委会负责。']];Object.assign(cmcPoint,{categoryId:'constitution-organs',title:'中央军委',summary:'完整还原性质、组成任期和领导体制。',preview:'武装力量领导机关；5年；无连续届数限制；主席负责制',keywords:['中央军事委员会','领导机关','5年','主席负责制'],aliases:['中央军委'],tags:['常识判断','法律常识','宪法','国家机构'],indexText:'中央军委小节含1个父知识点及3项内部分项。',sourceSections:[2],sourceUnitIds:[CENTRAL_MILITARY_COMMISSION_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'三句话绑定：性质是全国武装力量领导机关，任期随全国人大但主席无连续届数限制，体制实行主席负责制并对全国人大及常委会负责。',focus:[{label:'中央军委',note:'最易混的是“任期5年”不等于“连续任职有限制”；领导制度明确为主席负责制。',sourceUnitIds:[CENTRAL_MILITARY_COMMISSION_SOURCE_UNITS.table]}],route:['中央军委'],review:['中央军委是全国武装力量的领导机关。','组成：主席、副主席若干人、委员若干人；任期同全国人大，为5年。','中央军委主席没有连续任职届数限制；实行主席负责制，对全国人大及其常委会负责。']},tabs:[{id:'central-military-commission',title:'中央军委',blocks:[{type:'table',label:'中央军委',columns:['知识点','内部分项','完整内容'],rows,mergedCells:[{row:0,column:0,rowSpan:3}],mobileLayout:'cards',cardTitleColumn:1,cardGroupColumn:0,highlights:['领导机关','5年','没有连续任职届数限制','主席负责制'],sourceUnitIds:[CENTRAL_MILITARY_COMMISSION_SOURCE_UNITS.table]}]}]});}

  const judicialSystemPoint=(points||[]).find((item)=>item.id==='judicial-system');
  if(judicialSystemPoint){const courtRows=[['人民法院','1.性质与地位','我国的国家审判机关。'],['','2.组织体系','全国设最高人民法院、地方各级人民法院、专门人民法院。地方各级法院包括高级、中级、基层法院；专门法院包括军事、铁路运输、海事、森林法院等。'],['','3.领导体制','最高人民法院监督地方各级人民法院和专门人民法院的审判工作，上级人民法院监督下级人民法院的审判工作。（不是领导与被领导关系）'],['','4.审级制度','两审终审制。'],['','5.任期','最高人民法院院长每届任期同全国人大，连续任职不得超过两届。'],['','6.其他','审判公开原则和辩护原则：除法律规定特别情况外一律公开，被告人有权获得辩护。（补充：不公开情况为国家秘密、企业秘密、个人隐私）\n独立行使审判权：依法独立行使，不受行政机关、社会团体和个人干涉。']];const procuratorateRows=[['人民检察院','1.性质和地位','我国的国家法律监督机关。'],['','2.组织体系','全国设最高人民检察院、地方各级人民检察院和专门人民检察院。（地方各级包括省、市、县检察院；专门检察院包括军事、铁路运输检察院等。）'],['','3.领导体制','双重从属制：\n1.最高人民检察院领导地方各级和专门人民检察院工作，上级人民检察院领导下级人民检察院工作。\n2.最高人民检察院对全国人大和全国人大常委会负责；地方各级人民检察院对产生它的国家权力机关和上级人民检察院负责。'],['','4.任期','最高人民检察院检察长每届任期同全国人大，连续任职不得超过两届。']];Object.assign(judicialSystemPoint,{categoryId:'constitution-organs',title:'司法系统',summary:'按人民法院、人民检察院2个父知识点完整重建。',preview:'法院审判监督两审终审；检察法律监督领导双重从属',keywords:['国家审判机关','两审终审制','国家法律监督机关','双重从属制','监督关系','领导关系'],aliases:['法检系统'],tags:['常识判断','法律常识','宪法','国家机构'],indexText:'司法系统小节含法院检察院2个知识点。',sourceSections:[2,3],sourceUnitIds:[JUDICIAL_SYSTEM_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'用“法院监督、检察领导”先分上下级关系：法院负责审判并两审终审，检察院负责法律监督并实行上下领导、双重负责。',focus:[{label:'人民法院',note:'法院是审判机关；最高法和上级法院对下级是监督而非领导，一般两审终审并依法独立审判。',sourceUnitIds:[JUDICIAL_SYSTEM_SOURCE_UNITS.court]},{label:'人民检察院',note:'检察院是法律监督机关；上下级为领导关系，地方检察院同时对产生它的权力机关和上级检察院负责。',sourceUnitIds:[JUDICIAL_SYSTEM_SOURCE_UNITS.procuratorate]}],route:['人民法院','人民检察院'],review:['人民法院是国家审判机关；最高法、上级法院对下级法院是监督关系，不是领导关系。','法院一般实行两审终审；最高法院院长任期同全国人大，连续任职不超两届。','审判原则上公开并保障辩护；依法独立审判，不受行政机关、社会团体和个人干涉。','人民检察院是国家法律监督机关；最高检领导地方和专门检察院，上级检领导下级检。','检察院实行双重从属：地方检察院对产生它的权力机关和上级检察院负责。']},tabs:[{id:'peoples-court',title:'人民法院',blocks:[{type:'table',label:'人民法院',columns:['知识点','内部分项','完整内容'],rows:courtRows,mergedCells:[{row:0,column:0,rowSpan:6}],mobileLayout:'cards',cardTitleColumn:1,cardGroupColumn:0,highlights:['国家审判机关','监督','两审终审制','不得超过两届','独立行使审判权'],sourceUnitIds:[JUDICIAL_SYSTEM_SOURCE_UNITS.court]}]},{id:'peoples-procuratorate',title:'人民检察院',blocks:[{type:'table',label:'人民检察院',columns:['知识点','内部分项','完整内容'],rows:procuratorateRows,mergedCells:[{row:0,column:0,rowSpan:4}],mobileLayout:'cards',cardTitleColumn:1,cardGroupColumn:0,highlights:['国家法律监督机关','领导','双重从属制','负责','不得超过两届'],sourceUnitIds:[JUDICIAL_SYSTEM_SOURCE_UNITS.procuratorate]}]}]});}

  const nscPoint=(points||[]).find((item)=>item.id==='national-supervisory-commission');
  if(nscPoint){const rows=[['国家监察委员会','1.性质和地位','国家的监察机关；国家监察委员会是最高监察机关。'],['','2.组织体系','监察委员会由主任、副主任若干人、委员若干人组成。'],['','3.任期','监察委员会主任每届任期同本级人大；国家监察委员会主任连续任职不得超过两届。'],['','4.领导体制','国家监察委员会对全国人大和全国人大常委会负责；国家监察委员会领导地方各级监察委员会，上级监察委员会领导下级监察委员会，地方监察委员会对产生它的权力机关和上一级监察委员会负责；监察委员会依法独立行使监察权，不受行政机关、社会团体和个人干涉，办理职务违法犯罪案件与审判、检察、执法部门互相配合、互相制约。'],['','5.监察对象','补充：行使公权力的人员。\n1.党政、人大政协、监察司法、民主党派和工商联机关的公务员及参照公务员法管理人员。\n2.法律法规授权或受国家机关委托管理公共事务组织中从事公务的人员。\n3.国有企业人员。\n4.公办教育、科研、文化、医疗卫生、体育等单位中从事管理的人员。\n5.基层群众性自治组织中从事管理集体事务的人员。\n6.其他依法履行公职的人员。']];Object.assign(nscPoint,{categoryId:'constitution-organs',title:'国家监察委员会',summary:'完整还原性质、组织、任期、领导体制与6类监察对象。',preview:'最高监察机关；主任两届；上下领导；独立监察；公权力人员',keywords:['最高监察机关','领导','独立行使监察权','行使公权力','监察对象'],aliases:['国家监察委'],tags:['常识判断','法律常识','宪法','国家机构'],indexText:'国家监察委员会小节含1个父知识点及5项内部分项。',sourceSections:[3],sourceUnitIds:[NATIONAL_SUPERVISORY_COMMISSION_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'按“最高—组织—任期—领导—对象”串联，关系记上下级领导、地方双重负责，权力记独立监察，范围归结为所有行使公权力的公职人员。',focus:[{label:'国家监察委员会',note:'国家监察委是最高监察机关，主任任期随本级人大且不超两届；上下级为领导关系，监察权依法独立，监察对象覆盖6类公职人员。',sourceUnitIds:[NATIONAL_SUPERVISORY_COMMISSION_SOURCE_UNITS.table]}],route:['国家监察委员会'],review:['国家监察委员会是最高监察机关，由主任、副主任若干人、委员若干人组成。','主任任期同本级人大，国家监察委主任连续任职不超两届。','国家监察委领导地方监察委，上级领导下级；地方监察委对本级权力机关和上一级监察委负责。','监察委员会依法独立行使监察权，并与审判、检察、执法部门互相配合制约。','监察对象概括为行使公权力的人员，源文列举6类。']},tabs:[{id:'national-supervisory-commission',title:'国家监察委员会',blocks:[{type:'table',label:'国家监察委员会',columns:['知识点','内部分项','完整内容'],rows,mergedCells:[{row:0,column:0,rowSpan:5}],mobileLayout:'cards',cardTitleColumn:1,cardGroupColumn:0,highlights:['最高监察机关','不得超过两届','领导','独立行使监察权','行使公权力','6类'],sourceUnitIds:[NATIONAL_SUPERVISORY_COMMISSION_SOURCE_UNITS.table]}]}]});}

  const civilConceptPoint=(points||[]).find((item)=>item.id==='civil-code-general-persons');
  if(civilConceptPoint){const rows=[['民法的概念','1.概念','民法是调整平等主体的自然人、法人和非法人组织之间的人身关系和财产关系的法律规范的总称。'],['','2.结构','《民法典》共7编、1260条，总计10万余字。各编依次为总则、物权、合同、人格权、婚姻家庭、继承、侵权责任，以及附则。施行后，婚姻法、继承法、民法通则、收养法、担保法、合同法、物权法、侵权责任法、民法总则被替代。'],['','补充','人格权编：唯一新增单独成编的。']];Object.assign(civilConceptPoint,{categoryId:'civil-law-overview',title:'民法的概念',summary:'完整还原概念、民法典结构和人格权编补充。',preview:'平等主体；人身财产关系；7编1260条；人格权独立成编',keywords:['平等主体','人身关系','财产关系','7编','1260条','人格权编'],aliases:['民法概念'],tags:['常识判断','法律常识','民法典'],indexText:'民法概念小节含1个父知识点及3项内部分项。',sourceSections:[4],sourceUnitIds:[CIVIL_CONCEPT_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'先用“主体平等＋人身财产两类关系”锁定调整对象，再按七编顺序记结构，最后突出人格权是唯一新增独立成编。',focus:[{label:'民法的概念',note:'判断民法先看主体是否平等、关系是否为人身或财产；数字记7编1260条，人格权编是新增独立编。',sourceUnitIds:[CIVIL_CONCEPT_SOURCE_UNITS.table]}],route:['民法的概念'],review:['民法调整平等主体的自然人、法人、非法人组织之间的人身关系和财产关系。','民法典共7编1260条：总则、物权、合同、人格权、婚姻家庭、继承、侵权责任，另有附则。','人格权编是唯一新增单独成编。']},tabs:[{id:'civil-concept',title:'民法的概念',blocks:[{type:'table',label:'民法的概念',columns:['知识点','内部分项','完整内容'],rows,mergedCells:[{row:0,column:0,rowSpan:3}],mobileLayout:'cards',cardTitleColumn:1,cardGroupColumn:0,highlights:['平等主体','人身关系','财产关系','7编','1260条','人格权编'],sourceUnitIds:[CIVIL_CONCEPT_SOURCE_UNITS.table]}]}]});}

  const civilPrinciplesPoint=(points||[]).find((item)=>item.id==='civil-basic-principles');
  if(civilPrinciplesPoint){const rows=[['平等原则','首要原则；民事活动中法律地位一律平等。'],['自愿原则','核心原则，也称意思自治原则；按照自己的意思设立、变更、终止民事法律关系。做题关键词：愿意、强迫。'],['公平原则','合理确定各方的权利和义务。'],['诚信原则','帝王条款。'],['守法与公序良俗原则','不得违反法律，不得违背公序良俗。'],['绿色原则','也称绿色环保原则、保护生态环境原则。']];Object.assign(civilPrinciplesPoint,{categoryId:'civil-law-overview',title:'民法的基本原则',summary:'完整还原6项原则及括注定位。',preview:'平等首要；自愿核心；公平；诚信帝王；守法公序；绿色',keywords:rows.map(item=>item[0]),aliases:['民法六原则'],tags:['常识判断','法律常识','民法典'],indexText:'民法基本原则小节含6个知识点。',sourceSections:[4],sourceUnitIds:[CIVIL_BASIC_PRINCIPLES_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'按“平自公诚守绿”串联，定位词分别是首要、核心、权义平衡、帝王条款、法律与公序、生态环保。',focus:rows.map((item,index)=>({label:item[0],note:['法律地位一律平等，是民法首要原则。','意思自治是核心，愿意与强迫是判断线索。','以合理确定各方权利义务识别公平。','诚信原则要求民事活动诚实守信，定位词是帝王条款。','行为既不得违法，也不得违背公序良俗。','以节约资源、保护生态环境识别绿色原则。'][index],sourceUnitIds:[`cs-31-37-p4-civil-principle-kp-${index+1}`]})),route:['六项基本原则'],review:['口诀“平自公诚守绿”。','平等是首要原则；自愿是核心原则，又称意思自治。','公平要求合理确定权利义务；诚信是帝王条款。','守法与公序良俗要求不违法、不违背公序良俗；绿色原则强调生态环保。']},tabs:[{id:'civil-basic-principles',title:'六项基本原则',blocks:[{type:'table',label:'民法的基本原则',columns:['原则','核心含义'],rows,mobileLayout:'cards',cardTitleColumn:0,highlights:['首要原则','核心原则','帝王条款','公序良俗','绿色环保'],sourceUnitIds:[CIVIL_BASIC_PRINCIPLES_SOURCE_UNITS.table]}]}]});}

  const naturalPersonPoint=(points||[]).find((item)=>item.id==='civil-subjects');
  if(naturalPersonPoint){const definitionRows=[['自然人的定义','定义','自然人，是指依自然规律出生而取得民事主体资格的人。'],['','补充','包括试管、早产、剖腹产等；不包括克隆人、机器人等。']];const rightsRows=[['自然人的民事权利能力','1.概念','法律赋予民事主体享有民事权利和承担民事义务的能力，是民事主体享有权利承担义务的资格和进行民事活动的前提。始于出生，终于死亡。'],['','2.胎儿的民事权利能力','（1）正常情况下不具有民事权利能力。\n（2）涉及遗产继承、接受赠与等胎儿利益保护的，视为具有民事权利能力。\n（3）胎儿娩出时为死体的，民事权利能力自始不存在。']];const behaviorRows=[['自然人的民事行为能力','1.概念','—','自然人以自己行为取得民事权利、承担民事义务，依法独立进行民事活动的资格。'],['','2.分类','无民事行为能力','年龄：不满8周岁的未成年人。精神：不能辨认自己行为的成年人。其实施的民事法律行为无效，由法定代理人代理实施。'],['','','限制民事行为能力','年龄：8周岁以上的未成年人。精神：不能完全辨认自己行为的成年人。纯获利益或与年龄智力精神健康相适应的行为有效；单方民事法律行为无效；其他不相适应的行为效力待定，须代理或同意追认。'],['','','完全民事行为能力','年龄：年满18周岁；或年满16周岁、不满18周岁且以劳动收入为主要生活来源。精神正常；可独立实施行为并承担后果。'],['','补充','—','法定代理人一般指父母；纯获利益如压岁钱、接受赠与；做题时超过四位数通常视为与未成年人年龄智力不相适应。']];const absenceRows=[['宣告失踪和宣告死亡','1.宣告失踪','条件','下落不明满2年；由利害关系人向法院申请；人民法院依法宣告，公告期3个月。'],['','','效力','财产由配偶、成年子女、父母或其他愿意者代管；有争议等情形由法院指定。代管人代偿税款债务、行使债权并参与诉讼。诉讼离婚中应准予离婚。'],['','2.宣告死亡','条件','一般下落不明满4年（公告期1年）；意外事故满2年（公告期1年）；经有关机关证明不可能生还的，不受2年限制（公告期3个月）。由利害关系人申请、人民法院宣告。'],['','','效力','婚姻关系自死亡宣告之日起消除；个人合法财产按遗产继承；视为自然死亡并丧失民事主体资格；有权送养子女。'],['','','撤销死亡宣告','配偶未再婚的，婚姻关系自撤销宣告之日起自行恢复，但已再婚或书面声明不愿恢复除外；不得以未经本人同意主张收养无效，但收养人与被收养人同意除外；有权请求返还财产，无法返还应适当补偿。']];Object.assign(naturalPersonPoint,{categoryId:'civil-subjects-section',title:'自然人',summary:'按定义、权利能力、行为能力、宣告失踪死亡4个知识点完整重建。',preview:'出生死亡；胎儿利益；8-16-18；失踪2；死亡4/2；公告3月/1年',keywords:['自然人','民事权利能力','胎儿利益','民事行为能力','宣告失踪','宣告死亡'],aliases:['自然人民事主体'],tags:['常识判断','法律常识','民法典'],indexText:'自然人小节含4个知识点。',sourceSections:[5,6,7,8],sourceUnitIds:[NATURAL_PERSON_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'按“资格从出生—行为看8/16/18—失踪死亡看2/4/2”串联；胎儿利益是权利能力例外，宣告制度再绑定公告期、财产婚姻收养效果。',focus:[{label:'自然人的定义',note:'自然人以依自然规律出生为前提，试管早产剖腹产均包括，克隆人机器人不属于教材所指自然人。',sourceUnitIds:[NATURAL_PERSON_SOURCE_UNITS.definition]},{label:'自然人的民事权利能力',note:'权利能力始于出生终于死亡；胎儿通常不具有，但继承赠与等利益保护时视为具有，死体则自始不存在。',sourceUnitIds:[NATURAL_PERSON_SOURCE_UNITS.rightsCapacity]},{label:'自然人的民事行为能力',note:'年龄口诀8—16—18：不满8无能力，8以上限制，18完全；16至18靠劳动收入可视为完全。',sourceUnitIds:[NATURAL_PERSON_SOURCE_UNITS.behaviorCapacity]},{label:'宣告失踪和宣告死亡',note:'失踪记2年和财产代管；死亡记一般4年、意外2年，证明不可能生还不受2年限制，并区分婚姻收养财产效果。',sourceUnitIds:[NATURAL_PERSON_SOURCE_UNITS.absenceDeath]}],route:['自然人定义','民事权利能力','民事行为能力','失踪与死亡'],review:['自然人依自然规律出生；民事权利能力始于出生、终于死亡。','胎儿通常无权利能力，涉及继承赠与等利益时视为有；娩出死体自始不存在。','行为能力记8—16—18；限制行为能力人纯获利益或相适应行为有效，其他须区分无效与待定。','失踪满2年、公告3个月；死亡一般4年、意外2年，公告通常1年，证明不可能生还公告3个月。','死亡宣告影响婚姻、收养、继承和主体资格；撤销后婚姻恢复与财产返还均有例外。']},tabs:[{id:'natural-definition',title:'自然人定义',blocks:[{type:'table',label:'自然人的定义',columns:['知识点','内部分项','完整内容'],rows:definitionRows,mergedCells:[{row:0,column:0,rowSpan:2}],mobileLayout:'cards',cardTitleColumn:1,sourceUnitIds:[NATURAL_PERSON_SOURCE_UNITS.definition]}]},{id:'rights-capacity',title:'民事权利能力',blocks:[{type:'table',label:'自然人的民事权利能力',columns:['知识点','内部分项','完整内容'],rows:rightsRows,mergedCells:[{row:0,column:0,rowSpan:2}],mobileLayout:'cards',cardTitleColumn:1,sourceUnitIds:[NATURAL_PERSON_SOURCE_UNITS.rightsCapacity]}]},{id:'behavior-capacity',title:'民事行为能力',blocks:[{type:'table',label:'自然人的民事行为能力',columns:['知识点','内部分项','能力分类','完整内容'],rows:behaviorRows,mergedCells:[{row:0,column:0,rowSpan:5},{row:1,column:1,rowSpan:3}],mobileLayout:'cards',cardTitleColumn:2,sourceUnitIds:[NATURAL_PERSON_SOURCE_UNITS.behaviorCapacity]}]},{id:'absence-death',title:'失踪与死亡',blocks:[{type:'table',label:'宣告失踪和宣告死亡',columns:['知识点','制度','内部分项','完整内容'],rows:absenceRows,mergedCells:[{row:0,column:0,rowSpan:5},{row:0,column:1,rowSpan:2},{row:2,column:1,rowSpan:3}],mobileLayout:'cards',cardTitleColumn:2,sourceUnitIds:[NATURAL_PERSON_SOURCE_UNITS.absenceDeath]}]}]});}

  const legalPersonPoint=(points||[]).find((item)=>item.id==='legal-person');
  if(legalPersonPoint){const classificationRows=[['营利法人','以取得利润并分配给股东等出资人为目的成立的法人。','有限责任公司、股份有限公司和其他企业法人。（补充：外资企业）'],['非营利法人','为公益目的或者其他非营利目的成立，不向出资人、设立人或会员分配利润。','事业单位、社会团体、捐助法人（基金会、社会服务机构）。'],['特别法人','有独立经费的机关和承担行政职能的法定机构自成立之日起具有机关法人资格，可从事履职所需民事活动。','机关法人（人大、监察、审判、检察、军事等）、农村集体经济组织、合作经济组织、基层群众性自治组织。']];Object.assign(legalPersonPoint,{categoryId:'civil-subjects-section',title:'法人',summary:'按法人概述、法人分类2个知识点完整重建。',preview:'独立权利能力行为能力责任；营利非营利特别三类',keywords:['法人','全部财产','营利法人','非营利法人','特别法人'],aliases:['法人分类'],tags:['常识判断','法律常识','民法典'],indexText:'法人小节含2个知识点。',sourceSections:[8],sourceUnitIds:[LEGAL_PERSON_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'先抓法人“三独立”——独立享权、担义务、以全部财产担责；分类再按利润分配目的区分营利、非营利，剩余公共集体职能归特别法人。',focus:[{label:'法人概述',note:'法人同时具有民事权利能力和行为能力，能独立享权担义务，并以全部财产独立承担民事责任。',sourceUnitIds:[LEGAL_PERSON_SOURCE_UNITS.overview]},{label:'法人分类',note:'以活动性质分三类：向出资人分配利润为营利，不分配为非营利，机关和集体自治等特定组织为特别法人。',sourceUnitIds:[LEGAL_PERSON_SOURCE_UNITS.classification]}],route:['法人概述','法人分类'],review:['法人具有民事权利能力和行为能力，独立享权担义务，以全部财产独立担责。','营利法人以取得并向出资人分配利润为目的，包括有限责任公司、股份有限公司等。','非营利法人不向出资人设立人会员分配利润，包括事业单位、社会团体、捐助法人。','特别法人包括机关、农村集体经济组织、合作经济组织、基层群众性自治组织。']},tabs:[{id:'legal-person-overview',title:'法人概述',blocks:[{type:'list',label:'法人概述',items:['法人是具有民事权利能力和民事行为能力，依法独立享有民事权利和承担民事义务的组织。','法人以其全部财产独立承担民事责任。'],highlights:['民事权利能力','民事行为能力','独立','全部财产'],sourceUnitIds:[LEGAL_PERSON_SOURCE_UNITS.overview]}]},{id:'legal-person-classification',title:'法人分类',blocks:[{type:'table',label:'法人分类',columns:['类型','目的或性质','包括'],rows:classificationRows,mobileLayout:'cards',cardTitleColumn:0,highlights:['营利法人','非营利法人','特别法人','有限责任公司','股份有限公司','事业单位','社会团体','机关法人'],sourceUnitIds:[LEGAL_PERSON_SOURCE_UNITS.classification]}]}]});}

  const civilActConceptPoint=(points||[]).find((item)=>item.id==='civil-acts-agency-limitation');
  if(civilActConceptPoint) Object.assign(civilActConceptPoint,{categoryId:'civil-legal-acts-section',title:'概念',summary:'完整还原民事法律行为概念及四种效力类型。',preview:'意思表示；设立变更终止；有效无效待定可撤销',keywords:['民事法律行为','意思表示','设立','变更','终止'],aliases:['民事行为概念'],tags:['常识判断','法律常识','民法典'],indexText:'民事法律行为概念小节含1个知识点。',sourceSections:[9],sourceUnitIds:[CIVIL_ACT_CONCEPT_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'抓“意思表示＋设立变更终止”两个识别条件，再把法律效果分成有效、无效、效力待定、可撤销四类。',focus:[{label:'民事法律行为的概念',note:'民事主体通过意思表示设立、变更、终止民事法律关系；行为效果可能有效、无效、待定或可撤销。',sourceUnitIds:[CIVIL_ACT_CONCEPT_SOURCE_UNITS.concept]}],route:['民事法律行为概念'],review:['民事法律行为的主体是民事主体，核心方式是意思表示。','作用是设立、变更、终止民事法律关系。','效力分有效、无效、效力待定、可撤销四类。']},tabs:[{id:'civil-act-concept',title:'民事法律行为概念',blocks:[{type:'list',label:'民事法律行为的概念',items:['民事法律行为，是民事主体通过意思表示设立、变更、终止民事法律关系的行为。','它包括有效的民事法律行为、无效的民事法律行为、效力待定的民事法律行为以及可撤销的民事法律行为。'],highlights:['意思表示','设立','变更','终止','有效','无效','效力待定','可撤销'],sourceUnitIds:[CIVIL_ACT_CONCEPT_SOURCE_UNITS.concept]}]}]});

  const civilActEffectPoint=(points||[]).find((item)=>item.id==='civil-act-effect');
  if(civilActEffectPoint){const rows=[['有效的民事法律行为','—','（1）行为人具有相应民事行为能力；（2）意思表示真实；（3）不违反法律、行政法规的强制性规定，不违背公序良俗。口诀：法真行。','符合要件即有效。'],['无效的民事法律行为','欠缺根本生效要件，自始不发生预期效力。','（1）无民事行为能力人实施；（2）恶意串通损害他人合法权益；（3）违反法律行政法规强制性规定（不导致无效的除外）或违背公序良俗；（4）行为人与相对人以虚假的意思表示实施。口诀：小孩卖假串，缺德又违法。','自始无效。'],['可撤销的民事法律行为','已经成立生效，但因意思表示不真实，可经撤销使其自始无效。','重大误解、欺诈、胁迫、利用危困状态或缺乏判断能力致显失公平。口诀：诈迫误公。','一般自知悉撤销事由1年；重大误解90日；受胁迫自胁迫终止1年；行为发生后最长5年。撤销后自始无效。'],['效力待定的民事法律行为','效力须经有权人追认确定。','（1）无权代理；（2）限制民事行为能力人实施的超越能力行为。相对人可催告被代理人收到通知后30日内追认，未表示视为拒绝。','未追认合同无效；被追认或取得处分权的合同有效。']];Object.assign(civilActEffectPoint,{categoryId:'civil-legal-acts-section',title:'民事法律行为的效力',summary:'按有效、无效、可撤销、效力待定4个知识点完整重建。',preview:'法真行；小孩卖假串；诈迫误公；无权与限民30日追认',keywords:rows.map(item=>item[0]),aliases:['民事行为效力'],tags:['常识判断','法律常识','民法典'],indexText:'民事法律行为效力小节含4个知识点。',sourceSections:[9,10],sourceUnitIds:[CIVIL_ACT_EFFECT_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'先问是否满足“法真行”，再按瑕疵分流：根本欠缺直接无效，意思不真实可撤销，欠追认则效力待定；时间数字锁定1年、90日、5年、30日。',focus:rows.map((item,index)=>({label:item[0],note:['有效看行为能力、真实意思、不违法违俗三要件。','无效从一开始不生效，抓无能力、恶意串通、违法违俗、虚假表示。','可撤销在撤销前有效，事由记误解欺诈胁迫显失公平，期限记1年90日5年。','效力待定须追认，典型是无权代理与限民超越能力，催告期30日。'][index],sourceUnitIds:[`cs-31-37-p${index<2?'9':'9-p10'}-civil-act-effect-kp-${index+1}`]})),route:['四类效力'],review:['有效口诀“法真行”：能力相应、意思真实、不违法违俗。','无效自始无效：无能力、恶意串通、违法违俗、虚假表示。','可撤销事由：重大误解、欺诈、胁迫、显失公平；期限一般1年、误解90日、最长5年。','效力待定：无权代理、限民超越能力；催告追认期30日，未表示视为拒绝。']},tabs:[{id:'civil-act-four-effects',title:'四类效力',blocks:[{type:'table',label:'民事法律行为的效力',columns:['类型','定义','条件或情形','法律效果及期限'],rows,mobileLayout:'cards',cardTitleColumn:0,highlights:['法真行','自始无效','重大误解','欺诈','胁迫','显失公平','1年','90日','5年','无权代理','30日'],sourceUnitIds:[CIVIL_ACT_EFFECT_SOURCE_UNITS.table]}]}]});}

  const personalRightsPoint=(points||[]).find((item)=>item.id==='civil-rights');
  if(personalRightsPoint){const rows=[['人身自由和人格尊严','自然人的人身自由、人格尊严受法律保护。'],['人格权','自然人享有生命权、身体权、健康权、姓名权、肖像权、名誉权、荣誉权、隐私权、婚姻自主权等权利；法人、非法人组织享有名称权、名誉权和荣誉权。'],['个人信息保护','自然人的个人信息受法律保护。获取他人个人信息应依法取得并确保安全，不得非法收集、使用、加工、传输、买卖、提供或公开。'],['婚姻家庭关系中的人身权利','自然人因婚姻家庭关系等产生的人身权利受法律保护。']];Object.assign(personalRightsPoint,{categoryId:'civil-rights-section',title:'人身权',summary:'按人身自由人格尊严、人格权、个人信息、婚姻家庭人身权4个知识点完整重建。',preview:'人身自由人格尊严；自然人人格权；法人名称名誉荣誉；个人信息；婚姻家庭',keywords:['人身自由','人格尊严','人格权','个人信息','婚姻家庭'],aliases:['人身权利'],tags:['常识判断','法律常识','民法典'],indexText:'人身权小节含4个知识点。',sourceSections:[11],sourceUnitIds:[PERSONAL_RIGHTS_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'按“基本人格—权利清单—信息规则—家庭身份”展开：先保自由尊严，再区分自然人与法人组织的人格权，最后记个人信息禁止行为和婚姻家庭权利。',focus:rows.map((item,index)=>({label:item[0],note:['人身自由与人格尊严是自然人的基本人身保障。','自然人权利清单以生命身体健康开头；法人组织只有名称名誉荣誉三项。','个人信息须依法取得确保安全，并禁止七类非法处理行为。','婚姻家庭关系产生的人身权利同样受法律保护。'][index],sourceUnitIds:[`cs-31-37-p11-personal-rights-kp-${index+1}`]})),route:['人身权四项'],review:['自然人的人身自由、人格尊严受法律保护。','自然人享生命身体健康姓名肖像名誉荣誉隐私婚姻自主等权；法人非法人组织享名称名誉荣誉权。','个人信息须依法取得并确保安全，不得非法收集使用加工传输买卖提供公开。','婚姻家庭关系产生的人身权利受法律保护。']},tabs:[{id:'personal-rights-four',title:'人身权四项',blocks:[{type:'table',label:'人身权',columns:['知识点','完整内容'],rows,mobileLayout:'cards',cardTitleColumn:0,highlights:['人身自由','人格尊严','生命权','名称权','个人信息','婚姻家庭'],sourceUnitIds:[PERSONAL_RIGHTS_SOURCE_UNITS.table]}]}]});}

  const propertyRightsPoint=(points||[]).find((item)=>item.id==='civil-property-rights');
  if(propertyRightsPoint){const debtRows=[['合同之债','平等主体的自然人、法人或其他组织之间设立、变更、终止民事权利义务关系的协议所生之债。'],['侵权行为之债','不法侵害他人合法权益、依法应承担相应民事责任的行为所产生的债。'],['无因管理之债','没有法定或约定义务，为避免他人利益受损而管理或服务。管理人可请求受益人偿还必要费用，承担适当管理、通知、报告与计算义务；受益人负偿付义务。'],['见义勇为与紧急救助','因保护他人民事权益使自己受损，由侵权人承担民事责任，受益人可适当补偿；无侵权人、侵权人逃逸或无力承担时，受害人请求补偿的，受益人应适当补偿。自愿紧急救助造成受助人损害，救助人不承担民事责任。'],['不当得利之债','没有合法根据取得利益而使他人受损。受损方有权请求返还，得利方负返还义务；返还包括原物、原物孳息及利用原物所得其他利益。构成：一方得利、一方受损、得利受损有因果关系、无法律根据。'],['补充·孳息','天然孳息依自然规律产生，如剪下羊毛、摘下果实；法定孳息依民事法律关系产生，如利息、租金。']];Object.assign(propertyRightsPoint,{categoryId:'civil-rights-section',title:'财产权',summary:'按平等保护、物权、债权3个知识点完整重建。',preview:'财产权平等；所有用益担保；合同侵权无因管理不当得利；见义勇为',keywords:['财产权平等保护','所有权','用益物权','担保物权','合同之债','侵权之债','无因管理','不当得利'],aliases:['民事财产权'],tags:['常识判断','法律常识','民法典'],indexText:'财产权小节含3个知识点。',sourceSections:[11,12],sourceUnitIds:[CIVIL_PROPERTY_RIGHTS_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'先用“平等保护”总领，再把财产权分为物权和债权：物权记所有用益担保，债权按合同、侵权、无因管理、不当得利四条来源展开，并嵌入见义勇为规则。',focus:[{label:'财产权利平等保护',note:'民事主体的财产权利一律受法律平等保护，是物权与债权的总领规则。',sourceUnitIds:[CIVIL_PROPERTY_RIGHTS_SOURCE_UNITS.protection]},{label:'物权',note:'物权针对特定物，具有直接支配与排他性，内部分类为所有权、用益物权、担保物权。',sourceUnitIds:[CIVIL_PROPERTY_RIGHTS_SOURCE_UNITS.property]},{label:'债权',note:'债权请求特定义务人为或不为一定行为，来源记合同、侵权、无因管理、不当得利及法律其他规定。',sourceUnitIds:[CIVIL_PROPERTY_RIGHTS_SOURCE_UNITS.debt]}],route:['平等保护','物权','债权'],review:['民事主体财产权利受法律平等保护。','物权是对特定物直接支配和排他的权利，包括所有权、用益物权、担保物权。','债权来源：合同、侵权、无因管理、不当得利及法律其他规定。','无因管理中管理人可请求必要费用；见义勇为责任优先由侵权人承担，紧急救助人原则不担责。','不当得利四要件：得利、受损、因果、无法律根据；返还含原物、孳息及其他利益。']},tabs:[{id:'property-protection',title:'平等保护',blocks:[{type:'list',label:'财产权利平等保护',items:['民事主体的财产权利受法律平等保护。'],sourceUnitIds:[CIVIL_PROPERTY_RIGHTS_SOURCE_UNITS.protection]}]},{id:'property-right',title:'物权',blocks:[{type:'table',label:'物权',columns:['概念','分类'],rows:[['权利人依法对特定的物享有直接支配和排他的权利。','所有权、用益物权和担保物权。']],mobileLayout:'cards',cardTitleColumn:0,sourceUnitIds:[CIVIL_PROPERTY_RIGHTS_SOURCE_UNITS.property]}]},{id:'debt-right',title:'债权',blocks:[{type:'table',label:'债权',columns:['类型','完整内容'],rows:debtRows,mobileLayout:'cards',cardTitleColumn:0,highlights:['合同之债','侵权行为之债','无因管理','见义勇为','紧急救助','不当得利','天然孳息','法定孳息'],sourceUnitIds:[CIVIL_PROPERTY_RIGHTS_SOURCE_UNITS.debt]}]}]});}

  const agencyOverviewPoint=(points||[]).find((item)=>item.id==='civil-agency');
  if(agencyOverviewPoint) Object.assign(agencyOverviewPoint,{categoryId:'civil-agency-section',title:'概述',summary:'完整还原代理适用边界、法律效果和两类代理。',preview:'可代理；须亲自实施不得代理；权限内以本人名义；委托与法定',keywords:['代理人','本人亲自实施','代理权限','被代理人名义','委托代理','法定代理'],aliases:['代理概述'],tags:['常识判断','法律常识','民法典'],indexText:'代理概述小节含代理概述1个知识点及4项内部分项。',sourceSections:[12],sourceUnitIds:[AGENCY_OVERVIEW_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'先判断行为能否代理，再核对“权限内＋被代理人名义”，法律效果直接归被代理人；代理来源分委托与法定两类。',focus:[{label:'代理概述',note:'记“可代理有例外、行为须双限定、效果归本人、来源分两类”：依法依约或依性质须本人亲自实施的行为不得代理。',sourceUnitIds:[AGENCY_OVERVIEW_SOURCE_UNITS.overview]}],route:['代理概述'],review:['民事主体原则上可以通过代理人实施民事法律行为。','依法、依约或依行为性质须本人亲自实施的民事法律行为不得代理。','代理人在权限内以被代理人名义实施行为，法律效果由被代理人承受。','代理分委托代理和法定代理。']},tabs:[{id:'agency-overview',title:'代理概述',blocks:[{type:'list',label:'代理概述',items:['民事主体可以通过代理人实施民事法律行为。','依照法律规定、当事人约定或者民事法律行为的性质，应当由本人亲自实施的民事法律行为，不得代理。','代理人在代理权限内，以被代理人名义实施的民事法律行为，对被代理人发生效力。','代理包括委托代理和法定代理。'],subsections:[],highlights:['本人亲自实施','不得代理','代理权限内','被代理人名义','委托代理','法定代理'],sourceUnitIds:[AGENCY_OVERVIEW_SOURCE_UNITS.overview]}]}]});

  const agencyAuthorityPoint=(points||[]).find((item)=>item.id==='civil-agency-authority');
  if(agencyAuthorityPoint){const rows=[['代理权','1.代理权的行使','委托代理人按照被代理人的委托行使代理权；法定代理人依照法律规定行使代理权。补充：公司委托他人购买电脑属于委托代理；父母作为孩子的代理人属于法定代理。'],['','2.不履行或不完全履行职责','代理人不履行或者不完全履行职责，造成被代理人损害的，应当承担民事责任。'],['','3.恶意串通','代理人和相对人恶意串通，损害被代理人合法权益的，代理人和相对人应当承担连带责任。']];Object.assign(agencyAuthorityPoint,{categoryId:'civil-agency-section',title:'代理权',summary:'完整还原代理权行使依据及代理人两类责任。',preview:'委托依委托；法定依法律；不履责担责；恶意串通连带',keywords:['委托代理人','法定代理人','被代理人损害','恶意串通','连带责任'],aliases:['代理人责任'],tags:['常识判断','法律常识','民法典'],indexText:'代理权小节含代理权1个知识点及3项内部分项。',sourceSections:[12],sourceUnitIds:[AGENCY_AUTHORITY_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'按“权从何来—失职担责—串通连带”展开：委托代理按委托，法定代理按法律；造成被代理人损害时区分代理人单独责任与串通双方连带责任。',focus:[{label:'代理权',note:'行使依据分委托与法律；代理人不履责致损由代理人担责，代理人与相对人恶意串通则双方承担连带责任。',sourceUnitIds:[AGENCY_AUTHORITY_SOURCE_UNITS.table]}],route:['代理权'],review:['委托代理人依被代理人的委托行使代理权；法定代理人依法律规定行使代理权。','代理人不履行或不完全履行职责，造成被代理人损害，应承担民事责任。','代理人与相对人恶意串通损害被代理人合法权益，双方承担连带责任。']},tabs:[{id:'agency-authority',title:'代理权',blocks:[{type:'table',label:'代理权',columns:['知识点','内部分项','完整内容'],rows,mergedCells:[{row:0,column:0,rowSpan:3}],mobileLayout:'cards',cardTitleColumn:1,cardGroupColumn:0,highlights:['委托代理人','法定代理人','被代理人损害','恶意串通','连带责任'],sourceUnitIds:[AGENCY_AUTHORITY_SOURCE_UNITS.table]}]}]});}

  const unauthorizedAgencyPoint=(points||[]).find((item)=>item.id==='unauthorized-agency');
  if(unauthorizedAgencyPoint){const narrowRows=[['无权代理概念','无权代理是指非基于代理权，而以被代理人名义实施的，旨在将无权代理行为效果归属于被代理人的代理。'],['1.没有代理权之无权代理','行为人未得到被代理人授权，却以被代理人名义实施行为。'],['2.超越代理权之无权代理','行为人虽有代理权，但实施了超出授权范围的行为。'],['3.代理权终止后之无权代理','代理权已经终止，行为人仍以被代理人名义实施行为。']];const apparentRows=[['1.概念','表见代理是指由于本人的过失或基于本人与无权代理人之间的特殊关系，善意第三人确信无权代理人享有代理权而与之为民事行为，因而代理行为的法律效果直接归本人承受的一种特殊无权代理。'],['2.构成要件','（1）行为人无代理权：表见代理属于广义无权代理，只能在代理人无代理权而从事代理行为时发生。\n（2）行为人有相应的代理权外观：本人的授权行为已在外部形成表象，使第三人有合理理由相信行为人获得授权。\n（3）第三人为善意且无过失：不知道或不应当知道行为人实际无代理权，且这种不知道并非因疏忽大意或懈怠造成。'],['3.法律后果·外部关系','相对人主张代理行为有效时，表见代理与正常代理发生同样效果，代理行为设定的权利义务由本人承受。无权代理人因过失造成第三人损害的，第三人有权请求被代理人赔偿。'],['3.法律后果·内部关系','本人承受代理行为效果后如因此受损，有权向无权代理人请求赔偿。']];Object.assign(unauthorizedAgencyPoint,{categoryId:'civil-agency-section',title:'无权代理',summary:'按狭义无权代理、表见代理2个知识点完整重建。',preview:'无权超权权终；代理权外观；善意无过失；外部本人承受；内部追偿',keywords:['没有代理权','超越代理权','代理权终止','表见代理','代理权外观','善意无过失','相对人','无权代理人'],aliases:['狭义无权代理','表见代理'],tags:['常识判断','法律常识','民法典'],indexText:'无权代理小节含2个知识点及概念类型构成内外效果等内部分项。',sourceSections:[13],sourceUnitIds:[UNAUTHORIZED_AGENCY_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'先以“无权、超权、权终”识别狭义无权代理，再用“本无权、外观真、相对人善意无过失”判断表见代理，效果先外后内：本人对外承受、再向无权代理人追偿。',focus:[{label:'狭义无权代理',note:'先掌握无权代理概念，再按代理权状态分为从未取得、超越范围、权利终止后三类。',sourceUnitIds:[UNAUTHORIZED_AGENCY_SOURCE_UNITS.narrow]},{label:'表见代理',note:'构成记“行为人无权＋存在代理权外观＋第三人善意无过失”；对外由本人承受效果，对内本人可向无权代理人求偿。',sourceUnitIds:[UNAUTHORIZED_AGENCY_SOURCE_UNITS.apparent]}],route:['狭义无权代理','表见代理'],review:['无权代理是行为人非基于代理权、以被代理人名义实施并欲使效果归于被代理人的代理。','狭义无权代理三类：没有代理权、超越代理权、代理权终止后。','表见代理三要件：行为人无代理权、存在相应代理权外观、第三人善意且无过失。','外部关系中，相对人主张有效时权利义务由本人承受，第三人可请求被代理人赔偿。','内部关系中，本人承受效果并受损后，可向无权代理人请求赔偿。']},tabs:[{id:'narrow-unauthorized-agency',title:'狭义无权代理',blocks:[{type:'table',label:'狭义无权代理',columns:['内部分项','完整内容'],rows:narrowRows,mobileLayout:'cards',cardTitleColumn:0,highlights:['无权代理','没有代理权','超越代理权','代理权终止后'],sourceUnitIds:[UNAUTHORIZED_AGENCY_SOURCE_UNITS.narrow]}]},{id:'apparent-agency',title:'表见代理',blocks:[{type:'table',label:'表见代理',columns:['内部分项','完整内容'],rows:apparentRows,mobileLayout:'cards',cardTitleColumn:0,highlights:['无代理权','代理权外观','善意且无过失','相对人','被代理人','无权代理人'],sourceUnitIds:[UNAUTHORIZED_AGENCY_SOURCE_UNITS.apparent]}]}]});}

