  if(limitationConceptPoint) Object.assign(limitationConceptPoint,{categoryId:'civil-limitation-section',title:'概念',summary:'完整还原诉讼时效的概念及届满效果。',preview:'权利受侵害；法定期间不行使；丧失司法强制请求',keywords:['诉讼时效','法定时效期间','人民法院','强制履行'],aliases:['诉讼时效概念'],tags:['常识判断','法律常识','民法典'],indexText:'诉讼时效概念小节含1个知识点。',sourceSections:[14],sourceUnitIds:[CIVIL_LIMITATION_CONCEPT_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'抓“权利受侵害＋法定期间内不行使＋届满丧失司法强制保护”三层，时效届满影响的是请求法院强制履行的权利。',focus:[{label:'诉讼时效的概念',note:'权利人在法定期间内不行使权利，期间届满后丧失请求法院依诉讼程序强制义务人履行的权利。',sourceUnitIds:[CIVIL_LIMITATION_CONCEPT_SOURCE_UNITS.concept]}],route:['诉讼时效概念'],review:['诉讼时效以民事权利受到侵害为前提。','权利人在法定时效期间内不行使权利。','时效届满后，丧失的是请求法院依诉讼程序强制义务人履行的权利。']},tabs:[{id:'limitation-concept',title:'诉讼时效概念',blocks:[{type:'list',label:'诉讼时效的概念',items:['诉讼时效是指民事权利受到侵害的权利人在法定的时效期间内不行使权利，当时效期间届满时，即丧失了请求人民法院依诉讼程序强制义务人履行义务权利的制度。'],sourceUnitIds:[CIVIL_LIMITATION_CONCEPT_SOURCE_UNITS.concept]}]}]});

