  if(limitationTypesPoint){const ordinaryRows=[['1.期间','向人民法院请求保护民事权利的诉讼时效期间为3年。补充：此前为2年。'],['2.起算','自权利人知道或者应当知道权利受到损害以及义务人之日起计算；法律另有规定的，依照其规定。'],['3.最长期间','自权利受到损害之日起超过20年的，人民法院不予保护；有特殊情况的，人民法院可以根据权利人的申请决定延长。']];const specialRows=[['1.同一债务分期履行','自最后一期履行期限届满之日起计算。'],['2.无民事或限制民事行为能力人对法定代理人的请求权','自该法定代理终止之日起计算。'],['3.未成年人遭受性侵害的损害赔偿请求权','自受害人年满18周岁之日起计算。']];Object.assign(limitationTypesPoint,{categoryId:'civil-limitation-section',title:'诉讼时效的种类',summary:'按普通时效、特殊起算、不适用请求权3个知识点完整重建。',preview:'普通3年与最长20年；三类特殊起算；四类不适用',keywords:['3年','知道或者应当知道','20年','最后一期','法定代理终止','18周岁','不适用诉讼时效'],aliases:['诉讼时效种类'],tags:['常识判断','法律常识','民法典'],indexText:'诉讼时效种类小节含3个知识点及内部起算分项。',sourceSections:[14],sourceUnitIds:[CIVIL_LIMITATION_TYPES_SOURCE_UNITS.heading],sourceAuditStatus:'ready-for-user-acceptance',readingMeta:{label:'学习导读',takeaway:'先记普通规则“3年知损知人、最长20年”，再背三类特殊起算“最后一期、代理终止、年满18”，最后把停止侵害、返还特定物权财产、三费请求列为不适用。',focus:[{label:'普通诉讼时效',note:'数字锁定3年与20年：主观期间从知道或应知受损及义务人起算，客观最长期间从受损日起算。',sourceUnitIds:[CIVIL_LIMITATION_TYPES_SOURCE_UNITS.ordinary]},{label:'特殊诉讼时效',note:'三类起算点依次为最后一期届满、法定代理终止、受害人年满18周岁。',sourceUnitIds:[CIVIL_LIMITATION_TYPES_SOURCE_UNITS.special]},{label:'不适用诉讼时效的请求权',note:'按“停排消、返物、抚赡扶、法律其他”四组记忆。',sourceUnitIds:[CIVIL_LIMITATION_TYPES_SOURCE_UNITS.excluded]}],route:['普通诉讼时效','特殊诉讼时效','不适用诉讼时效'],review:['普通诉讼时效3年，从知道或应当知道权利受损及义务人之日起算。','最长保护期间原则为自权利受损日起20年，特殊情况可依申请延长。','特殊起算：分期债务最后一期届满；对法定代理人请求权自代理终止；未成年人性侵赔偿自年满18周岁。','停止侵害排除妨害消除危险、返还不动产或登记动产、支付抚养赡养扶养费等请求不适用诉讼时效。']},tabs:[{id:'ordinary-limitation',title:'普通诉讼时效',blocks:[{type:'table',label:'普通诉讼时效',columns:['内部分项','完整内容'],rows:ordinaryRows,mobileLayout:'cards',cardTitleColumn:0,highlights:['3年','知道或者应当知道','20年','申请决定延长'],sourceUnitIds:[CIVIL_LIMITATION_TYPES_SOURCE_UNITS.ordinary]}]},{id:'special-limitation',title:'特殊诉讼时效',blocks:[{type:'table',label:'特殊诉讼时效',columns:['内部分项','起算规则'],rows:specialRows,mobileLayout:'cards',cardTitleColumn:0,highlights:['最后一期','法定代理终止','18周岁'],sourceUnitIds:[CIVIL_LIMITATION_TYPES_SOURCE_UNITS.special]}]},{id:'no-limitation',title:'不适用诉讼时效',blocks:[{type:'list',label:'不适用诉讼时效的请求权',items:['请求停止侵害、排除妨害、消除危险。','不动产物权和登记的动产物权的权利人请求返还财产。','请求支付抚养费、赡养费或者扶养费。','依法不适用诉讼时效的其他请求权。'],sourceUnitIds:[CIVIL_LIMITATION_TYPES_SOURCE_UNITS.excluded]}]}]});}

